def system_volume(level, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.fromtimestamp(float(s), tz=datetime.timezone.utc)
        if isinstance(s, str):
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except ValueError:
                return None
        return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    tool_name = "system_volume"

    # ---- validate inputs (schema) ----
    if level is None or not isinstance(level, (int, float)) or isinstance(level, bool):
        # bool is subclass of int, exclude
        # log failed execution (as per business rules)
        req_params = {"level": level}
        exec_row = None
        try:
            host_id = _extra.get("host_device_id")
            # proceed to auth to log under a client if possible; if not, still attempt host validation and log later
        except Exception:
            host_id = None
        # We'll authenticate first if possible; if not, return validation error without execution row? Rule says invalid params must produce failed execution.
        # We can still create an execution row after resolving auth/host; if impossible, return validation error.
        # So validate fully but still do auth/log path below with error_type='validation_error'.
        validation_error = "Parameter 'level' must be a number between 0 and 100."
    else:
        validation_error = None

    if validation_error is None:
        if level < 0 or level > 100:
            validation_error = "Parameter 'level' must be between 0 and 100."

    # ---- load datastore ----
    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    tool_policies = _load("tool_policies.json")
    tool_executions = _load("tool_executions.json")
    usage_quotas = _load("usage_quotas.json")
    hosts = _load("host_identities.json")

    # ---- resolve host_device_id ----
    host_device_id = _extra.get("host_device_id")
    host_ok = False
    if isinstance(host_device_id, str) and host_device_id.strip():
        if isinstance(hosts, list) and hosts:
            for h in hosts:
                if isinstance(h, dict) and h.get("id") == host_device_id:
                    if h.get("status") in (None, "active", "enabled"):
                        host_ok = True
                        break
        else:
            # If the server has no configured hosts file/rows, treat mismatch as unauthorized (cannot verify).
            host_ok = False

    # ---- authenticate (ambient) ----
    now = _now_iso()
    now_dt = _parse_dt(now)

    def _key_is_usable(krow):
        if not isinstance(krow, dict):
            return False
        if krow.get("status") != "active":
            return False
        exp = _parse_dt(krow.get("expires_at"))
        if exp is not None and now_dt is not None and exp <= now_dt:
            return False
        cid = krow.get("client_id")
        if not cid:
            return False
        client = next((c for c in api_clients if isinstance(c, dict) and c.get("id") == cid), None)
        if not client or client.get("status") != "active":
            return False
        return True

    # Tool carries no credential param: select a usable key+client combination that can satisfy policies/quotas.
    usable_keys = [k for k in api_keys if _key_is_usable(k)]
    if not usable_keys:
        # cannot create execution row without a client_id; return unauthorized
        return _err("UNAUTHORIZED", "No active API key/client available for this request.")

    # For deterministic choice, sort by updated_at/created_at descending if present
    def _sort_key(k):
        dt = _parse_dt(k.get("last_used_at")) or _parse_dt(k.get("updated_at")) or _parse_dt(k.get("created_at"))
        return dt.timestamp() if dt else 0.0

    usable_keys.sort(key=_sort_key, reverse=True)

    chosen_key = None
    chosen_client = None
    chosen_policy = None

    # policy default-deny if no row exists
    def _get_policy(client_id):
        pol = next(
            (
                p
                for p in tool_policies
                if isinstance(p, dict)
                and p.get("client_id") == client_id
                and p.get("tool_name") == tool_name
                and p.get("status") == "active"
            ),
            None,
        )
        return pol

    for k in usable_keys:
        cid = k.get("client_id")
        pol = _get_policy(cid)
        # if no policy: default deny => not usable for success, but could still be used to log failed execution
        if pol and pol.get("effect") == "allow":
            chosen_key, chosen_client, chosen_policy = k, next(c for c in api_clients if c.get("id") == cid), pol
            break

    # If no allowed policy exists for any usable key, still select a usable key to log policy_denied (consistent default-deny)
    if chosen_key is None:
        chosen_key = usable_keys[0]
        cid = chosen_key.get("client_id")
        chosen_client = next((c for c in api_clients if isinstance(c, dict) and c.get("id") == cid), None)
        chosen_policy = _get_policy(cid)  # may be None (default deny)

    client_id = chosen_client.get("id") if chosen_client else None
    api_key_id = chosen_key.get("id") if chosen_key else None

    # ---- effective params (defaulting) ----
    request_params = {"level": level}

    # ---- build execution row (always for this tool call, including reads and failures) ----
    exec_id = _gen_id("exec")
    exec_row = {
        "id": exec_id,
        "client_id": client_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "status": "queued",
        "request_params": request_params,
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": host_device_id if isinstance(host_device_id, str) else "",
        "duration_ms": None,
        "normalized": {"level": level} if validation_error is None else None,
        "created_at": now,
        "updated_at": now,
        "started_at": None,
        "finished_at": None,
    }
    tool_executions.append(exec_row)

    def _finalize_failed(err_type, err_msg, code):
        end = _now_iso()
        exec_row["updated_at"] = end
        exec_row["status"] = "failed"
        exec_row["error_type"] = err_type
        exec_row["error_message"] = err_msg
        exec_row["finished_at"] = end
        exec_row["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
        # persist execution + last_used only on success; but executions must be persisted always
        _save("tool_executions.json", tool_executions)
        return _err(code, err_msg, execution_id=exec_id)

    def _finalize_succeeded(result):
        end = _now_iso()
        exec_row["status"] = "succeeded"
        exec_row["result_data"] = result
        exec_row["updated_at"] = end
        exec_row["finished_at"] = end
        exec_row["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
        _save("tool_executions.json", tool_executions)

        # update key last_used_at on success
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = end
                k["updated_at"] = end
                break
        _save("api_keys.json", api_keys)
        return {
            "execution_id": exec_id,
            "tool_name": tool_name,
            "status": "succeeded",
            "result": result,
        }

    # ---- host validation ----
    if not host_ok:
        return _finalize_failed("validation_error", "host_device_id is invalid or not configured on this server.", "VALIDATION_ERROR")

    # ---- input validation failure ----
    if validation_error is not None:
        return _finalize_failed("validation_error", validation_error, "VALIDATION_ERROR")

    # ---- policy check (default deny) ----
    if not chosen_policy or chosen_policy.get("effect") != "allow":
        return _finalize_failed("policy_denied", "Tool is not permitted for this client.", "UNAUTHORIZED")

    # enforce policy parameter constraints for system_volume.volume_max
    pc = chosen_policy.get("parameter_constraints") if isinstance(chosen_policy, dict) else None
    if isinstance(pc, dict) and "volume_max" in pc and pc["volume_max"] is not None:
        vmax = pc["volume_max"]
        if not isinstance(vmax, (int, float)) or isinstance(vmax, bool) or vmax < 0 or vmax > 100:
            return _finalize_failed("validation_error", "Server policy misconfigured: volume_max must be 0..100.", "VALIDATION_ERROR")
        if level > vmax:
            return _finalize_failed("policy_denied", f"Requested volume {level} exceeds policy maximum {vmax}.", "UNAUTHORIZED")

    # ---- quota enforcement (active quotas, all_tools + tool) ----
    active_quotas = [
        q for q in usage_quotas
        if isinstance(q, dict)
        and q.get("client_id") == client_id
        and q.get("status") == "active"
        and isinstance(q.get("window_seconds"), int)
        and isinstance(q.get("max_requests"), int)
    ]

    def _count_within(window_seconds, tool_specific):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for e in tool_executions:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id:
                continue
            if tool_specific and e.get("tool_name") != tool_name:
                continue
            created = _parse_dt(e.get("created_at"))
            if created is None:
                continue
            if created >= cutoff:
                cnt += 1
        return cnt

    # If this request would exceed any quota, reject.
    for q in active_quotas:
        scope = q.get("scope")
        ws = q.get("window_seconds")
        mr = q.get("max_requests")
        if scope == "all_tools":
            if q.get("tool_name") is not None:
                continue
            used = _count_within(ws, tool_specific=False)
            if used > mr:
                return _finalize_failed("rate_limit", "Client has exceeded its quota for all tools.", "QUOTA_EXCEEDED")
        elif scope == "tool":
            if q.get("tool_name") != tool_name:
                continue
            used = _count_within(ws, tool_specific=True)
            if used > mr:
                return _finalize_failed("rate_limit", "Client has exceeded its quota for this tool.", "QUOTA_EXCEEDED")

    # ---- perform "execution" ----
    # Offline datastore-backed behavior: record applied volume in a local state file.
    exec_row["status"] = "running"
    exec_row["started_at"] = _now_iso()
    exec_row["updated_at"] = exec_row["started_at"]
    _save("tool_executions.json", tool_executions)

    state = _load("system_state.json")
    if not isinstance(state, dict):
        state = {}
    state["volume_level"] = float(level)
    state["updated_at"] = _now_iso()
    _save("system_state.json", state)

    return _finalize_succeeded({"applied_level": float(level)})

