        return next(
            (
                p
                for p in tool_policies
                if isinstance(p, dict)
                and p.get("client_id") == client_id
                and p.get("tool_name") == tool_name
                and p.get("status") == "active"
            ),
            None,
        )

    chosen_key = None
    chosen_client = None
    chosen_policy = None
    for k in usable_keys:
        cid = k.get("client_id")
        pol = _get_policy(cid)
        if pol and pol.get("effect") == "allow":
            chosen_key, chosen_client, chosen_policy = k, next(c for c in api_clients if c.get("id") == cid), pol
            break
    if chosen_key is None:
        chosen_key = usable_keys[0]
        cid = chosen_key.get("client_id")
        chosen_client = next((c for c in api_clients if isinstance(c, dict) and c.get("id") == cid), None)
        chosen_policy = _get_policy(cid)

    client_id = chosen_client.get("id") if chosen_client else None
    api_key_id = chosen_key.get("id") if chosen_key else None

    exec_id = _gen_id("exec")
    exec_row = {
        "id": exec_id,
        "client_id": client_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
