        cnt = 0
        for e in tool_executions:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id:
                continue
            if tool_specific and e.get("tool_name") != tool_name:
                continue
            created = _parse_dt(e.get("created_at"))
            if created is None:
                continue
            if created >= cutoff:
                cnt += 1
        return cnt

    for q in active_quotas:
        scope = q.get("scope")
        ws = q.get("window_seconds")
        mr = q.get("max_requests")
        if scope == "all_tools":
            if q.get("tool_name") is not None:
                continue
            used = _count_within(ws, tool_specific=False)
            if used > mr:
                return _finalize_failed("rate_limit", "Client has exceeded its quota for all tools.", "QUOTA_EXCEEDED")
        elif scope == "tool":
            if q.get("tool_name") != tool_name:
                continue
            used = _count_within(ws, tool_specific=True)
            if used > mr:
                return _finalize_failed("rate_limit", "Client has exceeded its quota for this tool.", "QUOTA_EXCEEDED")

    exec_row["status"] = "running"
    exec_row["started_at"] = _now_iso()
    exec_row["updated_at"] = exec_row["started_at"]
    _save("tool_executions.json", tool_executions)

    # Offline state-based frontmost app (if present)
    state = _load("system_state.json")
    app = None
    if isinstance(state, dict):
        app = state.get("frontmost_app")
    if not isinstance(app, str) or not app.strip():
        # reasonable deterministic fallback
        app = "Finder"

    return _finalize_succeeded({"name": app})

