        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": host_device_id if isinstance(host_device_id, str) else "",
        "duration_ms": None,
        "normalized": {"app_name": name} if validation_error is None else None,
        "created_at": now,
        "updated_at": now,
        "started_at": None,
        "finished_at": None,
    }
    tool_executions.append(exec_row)

    def _finalize_failed(err_type, err_msg, code):
        end = _now_iso()
        exec_row["updated_at"] = end
        exec_row["status"] = "failed"
        exec_row["error_type"] = err_type
        exec_row["error_message"] = err_msg
        exec_row["finished_at"] = end
        exec_row["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
        _save("tool_executions.json", tool_executions)
        return _err(code, err_msg, execution_id=exec_id)

    def _finalize_succeeded(result):
        end = _now_iso()
        exec_row["status"] = "succeeded"
        exec_row["result_data"] = result
        exec_row["updated_at"] = end
        exec_row["finished_at"] = end
        exec_row["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
        _save("tool_executions.json", tool_executions)

        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = end
                k["updated_at"] = end
                break
        _save("api_keys.json", api_keys)
        return {
            "execution_id": exec_id,
            "tool_name": tool_name,
            "status": "succeeded",
            "result": result,
        }

    if not host_ok:
        return _finalize_failed("validation_error", "host_device_id is invalid or not configured on this server.", "VALIDATION_ERROR")

    if validation_error is not None:
        return _finalize_failed("validation_error", validation_error, "VALIDATION_ERROR")

    if not chosen_policy or chosen_policy.get("effect") != "allow":
        return _finalize_failed("policy_denied", "Tool is not permitted for this client.", "UNAUTHORIZED")

    # quota enforcement
    active_quotas = [
        q for q in usage_quotas
        if isinstance(q, dict)
        and q.get("client_id") == client_id
        and q.get("status") == "active"
        and isinstance(q.get("window_seconds"), int)
        and isinstance(q.get("max_requests"), int)
    ]

    def _count_within(window_seconds, tool_specific):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for e in tool_executions:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id:
                continue
            if tool_specific and e.get("tool_name") != tool_name:
                continue
            created = _parse_dt(e.get("created_at"))
            if created is None:
                continue
            if created >= cutoff:
                cnt += 1
        return cnt

    for q in active_quotas:
        scope = q.get("scope")
        ws = q.get("window_seconds")
        mr = q.get("max_requests")
        if scope == "all_tools":
            if q.get("tool_name") is not None:
                continue
            used = _count_within(ws, tool_specific=False)
            if used > mr:
                return _finalize_failed("rate_limit", "Client has exceeded its quota for all tools.", "QUOTA_EXCEEDED")
        elif scope == "tool":
            if q.get("tool_name") != tool_name:
                continue
            used = _count_within(ws, tool_specific=True)
            if used > mr:
                return _finalize_failed("rate_limit", "Client has exceeded its quota for this tool.", "QUOTA_EXCEEDED")

    exec_row["status"] = "running"
    exec_row["started_at"] = _now_iso()
    exec_row["updated_at"] = exec_row["started_at"]
    _save("tool_executions.json", tool_executions)

    # Offline "app registry" enforcement: if configured, require app exists.
    apps = _load("installed_apps.json")
    if isinstance(apps, list) and apps:
        found = any(isinstance(a, dict) and (a.get("name") == name) for a in apps) or any(isinstance(a, str) and a == name for a in apps)
        if not found:
            return _finalize_failed("not_found", "Application not found.", "NOT_FOUND")

    state = _load("system_state.json")
    if not isinstance(state, dict):
        state = {}
    running = state.get("running_apps")
    if not isinstance(running, list):
        running = []
    already_running = name in running
    if not already_running:
        running.append(name)
    state["running_apps"] = running
    state["frontmost_app"] = name
    state["updated_at"] = _now_iso()
    _save("system_state.json", state)

    return _finalize_succeeded({"name": name, "already_running": bool(already_running)})

def system_quit_app(name, force=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.fromtimestamp(float(s), tz=datetime.timezone.utc)
        if isinstance(s, str):
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except ValueError:
                return None
        return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    tool_name = "system_quit_app"

    # validate inputs & defaults
    validation_error = None
    if not isinstance(name, str) or not name.strip():
        validation_error = "Parameter 'name' is required and must be a non-empty string."
    else:
        name = name.strip()

    if force is None:
        force_eff = False
    elif isinstance(force, bool):
        force_eff = force
    else:
        validation_error = validation_error or "Parameter 'force' must be a boolean if provided."
        force_eff = False

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    tool_policies = _load("tool_policies.json")
    tool_executions = _load("tool_executions.json")
    usage_quotas = _load("usage_quotas.json")
    hosts = _load("host_identities.json")

    host_device_id = _extra.get("host_device_id")
    host_ok = False
    if isinstance(host_device_id, str) and host_device_id.strip():
        if isinstance(hosts, list) and hosts:
            for h in hosts:
                if isinstance(h, dict) and h.get("id") == host_device_id:
                    if h.get("status") in (None, "active", "enabled"):
                        host_ok = True
                        break

    now = _now_iso()
    now_dt = _parse_dt(now)

    def _key_is_usable(krow):
        if not isinstance(krow, dict):
            return False
        if krow.get("status") != "active":
            return False
        exp = _parse_dt(krow.get("expires_at"))
        if exp is not None and now_dt is not None and exp <= now_dt:
            return False
        cid = krow.get("client_id")
        client = next((c for c in api_clients if isinstance(c, dict) and c.get("id") == cid), None)
        if not client or client.get("status") != "active":
            return False
        return True

    usable_keys = [k for k in api_keys if _key_is_usable(k)]
    if not usable_keys:
        return _err("UNAUTHORIZED", "No active API key/client available for this request.")

    def _sort_key(k):
        dt = _parse_dt(k.get("last_used_at")) or _parse_dt(k.get("updated_at")) or _parse_dt(k.get("created_at"))
        return dt.timestamp() if dt else 0.0

    usable_keys.sort(key=_sort_key, reverse=True)

    def _get_policy(client_id):
        return next(
            (
                p
                for p in tool_policies
                if isinstance(p, dict)
                and p.get("client_id") == client_id
                and p.get("tool_name") == tool_name
                and p.get("status") == "active"
            ),
            None,
        )

    chosen_key = None
    chosen_client = None
    chosen_policy = None
    for k in usable_keys:
        cid = k.get("client_id")
        pol = _get_policy(cid)
        if pol and pol.get("effect") == "allow":
            chosen_key, chosen_client, chosen_policy = k, next(c for c in api_clients if c.get("id") == cid), pol
            break
    if chosen_key is None:
        chosen_key = usable_keys[0]
        cid = chosen_key.get("client_id")
        chosen_client = next((c for c in api_clients if isinstance(c, dict) and c.get("id") == cid), None)
        chosen_policy = _get_policy(cid)

    client_id = chosen_client.get("id") if chosen_client else None
    api_key_id = chosen_key.get("id") if chosen_key else None

    request_params = {"name": name, "force": bool(force_eff)}

    exec_id = _gen_id("exec")
    exec_row = {
        "id": exec_id,
        "client_id": client_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "status": "queued",
        "request_params": request_params,
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": host_device_id if isinstance(host_device_id, str) else "",
        "duration_ms": None,
        "normalized": {"app_name": name, "force": bool(force_eff)} if validation_error is None else None,
        "created_at": now,
        "updated_at": now,
        "started_at": None,
        "finished_at": None,
    }
    tool_executions.append(exec_row)

    def _finalize_failed(err_type, err_msg, code):
        end = _now_iso()
        exec_row["updated_at"] = end
        exec_row["status"] = "failed"
        exec_row["error_type"] = err_type
        exec_row["error_message"] = err_msg
        exec_row["finished_at"] = end
        exec_row["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
        _save("tool_executions.json", tool_executions)
        return _err(code, err_msg, execution_id=exec_id)

    def _finalize_succeeded(result):
        end = _now_iso()
        exec_row["status"] = "succeeded"
        exec_row["result_data"] = result
        exec_row["updated_at"] = end
        exec_row["finished_at"] = end
        exec_row["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
        _save("tool_executions.json", tool_executions)

        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = end
                k["updated_at"] = end
                break
        _save("api_keys.json", api_keys)
        return {
            "execution_id": exec_id,
            "tool_name": tool_name,
            "status": "succeeded",
            "result": result,
        }

    if not host_ok:
        return _finalize_failed("validation_error", "host_device_id is invalid or not configured on this server.", "VALIDATION_ERROR")

    if validation_error is not None:
        return _finalize_failed("validation_error", validation_error, "VALIDATION_ERROR")

    if not chosen_policy or chosen_policy.get("effect") != "allow":
        return _finalize_failed("policy_denied", "Tool is not permitted for this client.", "UNAUTHORIZED")

    # quota enforcement
    active_quotas = [
        q for q in usage_quotas
        if isinstance(q, dict)
        and q.get("client_id") == client_id
        and q.get("status") == "active"
        and isinstance(q.get("window_seconds"), int)
        and isinstance(q.get("max_requests"), int)
    ]

    def _count_within(window_seconds, tool_specific):
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for e in tool_executions:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id:
                continue
            if tool_specific and e.get("tool_name") != tool_name:
                continue
            created = _parse_dt(e.get("created_at"))
            if created is None:
                continue
            if created >= cutoff:
                cnt += 1
        return cnt

    for q in active_quotas:
        scope = q.get("scope")
        ws = q.get("window_seconds")
        mr = q.get("max_requests")
        if scope == "all_tools":
            if q.get("tool_name") is not None:
                continue
            used = _count_within(ws, tool_specific=False)
            if used > mr:
                return _finalize_failed("rate_limit", "Client has exceeded its quota for all tools.", "QUOTA_EXCEEDED")
        elif scope == "tool":
            if q.get("tool_name") != tool_name:
                continue
            used = _count_within(ws, tool_specific=True)
            if used > mr:
                return _finalize_failed("rate_limit", "Client has exceeded its quota for this tool.", "QUOTA_EXCEEDED")

    exec_row["status"] = "running"
    exec_row["started_at"] = _now_iso()
    exec_row["updated_at"] = exec_row["started_at"]
    _save("tool_executions.json", tool_executions)

    # Offline process state
    state = _load("system_state.json")
    if not isinstance(state, dict):
        state = {}
    running = state.get("running_apps")
    if not isinstance(running, list):
        running = []

    if name not in running:
        return _finalize_failed("not_found", "Application is not running.", "NOT_FOUND")

    # quit
    running = [a for a in running if a != name]
    state["running_apps"] = running
    if state.get("frontmost_app") == name:
        state["frontmost_app"] = running[-1] if running else "Finder"
    state["updated_at"] = _now_iso()
    _save("system_state.json", state)

    method = "force" if force_eff else "graceful"
    return _finalize_succeeded({"name": name, "method": method})

def system_toggle_dark_mode(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tool_name = "system_toggle_dark_mode"
    allowed_tools = {
        "system_volume", "system_get_frontmost_app", "system_launch_app", "system_quit_app",
        "system_toggle_dark_mode", "system_get_battery_status", "calendar_add", "calendar_list",
        "finder_get_selected_files", "finder_search_files", "finder_quick_look_file",
        "clipboard_get_clipboard", "clipboard_set_clipboard", "clipboard_clear_clipboard",
        "notifications_toggle_do_not_disturb", "notifications_send_notification",
        "iterm_paste_clipboard", "iterm_run", "mail_create_email", "mail_list_emails",
        "mail_get_email", "pages_create_document", "shortcuts_run_shortcut",
        "shortcuts_list_shortcuts", "messages_list_chats", "messages_get_messages",
        "messages_search_messages", "messages_compose_message", "notes_create",
        "notes_createRawHtml", "notes_list", "notes_get", "notes_search"
    }
    if tool_name not in allowed_tools:
        return _err("VALIDATION_ERROR", "Unknown tool_name")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    tool_policies = _load("tool_policies.json")
    quotas = _load("usage_quotas.json")
    executions = _load("tool_executions.json")

    # Resolve a usable (active, unexpired) api_key whose client is active (ambient auth).
    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow()

    usable_pairs = []
    client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now_dt:
            continue
        cid = k.get("client_id")
        c = client_by_id.get(cid)
        if not c or c.get("status") != "active":
            continue
        usable_pairs.append((c, k))

    # Also require host_device_id to match configured host identities. Model: any host_device_id present in existing executions.
    known_hosts = set()
    for e in executions:
        if isinstance(e, dict) and e.get("host_device_id"):
            known_hosts.add(e.get("host_device_id"))
    if not known_hosts:
        # Server must have configured host identities; if none in store, cannot validate.
        return _err("UNAUTHORIZED", "No configured host identities available")

    host_device_id = sorted(known_hosts)[0]

    if not usable_pairs:
        # Log failed execution attempt? Business rules say every tool call must authenticate; if invalid, reject.
        return _err("UNAUTHORIZED", "No active, unexpired API key for an active client is available")

    # Evaluate policy: default deny if no policy exists.
    def _policy_for(client_id, tool):
        for p in tool_policies:
            if not isinstance(p, dict):
                continue
            if p.get("client_id") == client_id and p.get("tool_name") == tool and p.get("status") == "active":
                return p
        return None

    # Find a client/key pair that is allowed and within quota
    chosen = None
    denial_reason = None

    def _count_recent(client_id, tool, window_seconds, scope, scope_tool_name):
        cutoff = now_dt - datetime.timedelta(seconds=window_seconds)
        n = 0
        for e in executions:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id:
                continue
            created = _parse_dt(e.get("created_at"))
            if created is None or created < cutoff:
                continue
            if scope == "all_tools":
                n += 1
            else:
                if e.get("tool_name") == scope_tool_name:
                    n += 1
        return n

    def _check_quota(client_id, tool):
        # active quotas for all_tools and tool; both enforced
        for q in quotas:
            if not isinstance(q, dict):
                continue
            if q.get("client_id") != client_id or q.get("status") != "active":
                continue
            scope = q.get("scope")
            w = q.get("window_seconds")
            m = q.get("max_requests")
            if not isinstance(w, int) or w < 1 or w > 86400:
                continue
            if not isinstance(m, int) or m < 1 or m > 100000:
                continue
            if scope == "all_tools":
                if q.get("tool_name") is not None:
                    continue
                if _count_recent(client_id, tool, w, "all_tools", None) + 1 > m:
                    return False, {"scope": "all_tools", "window_seconds": w, "max_requests": m}
            elif scope == "tool":
                tn = q.get("tool_name")
                if tn != tool:
                    continue
                if _count_recent(client_id, tool, w, "tool", tool) + 1 > m:
                    return False, {"scope": "tool", "tool_name": tool, "window_seconds": w, "max_requests": m}
        return True, None

    for c, k in usable_pairs:
        pol = _policy_for(c["id"], tool_name)
        if pol is None or pol.get("effect") != "allow":
            denial_reason = "policy_denied"
            continue
        okq, qinfo = _check_quota(c["id"], tool_name)
        if not okq:
            denial_reason = ("quota", qinfo)
            continue
        chosen = (c, k, pol)
        break

    # Create execution row helper
    def _new_exec_id():
        return "exec_" + uuid.uuid4().hex

    def _append_execution(row):
        executions.append(row)
        _save("tool_executions.json", executions)

    if chosen is None:
        # If any pair exists but policy denied: create failed execution (policy_denied) using first usable pair's client/key.
        c, k = usable_pairs[0]
        exec_row = {
            "id": _new_exec_id(),
            "client_id": c["id"],
            "api_key_id": k.get("id"),
            "tool_name": tool_name,
            "status": "failed",
            "request_params": {},
            "result_data": None,
            "error_type": "policy_denied" if denial_reason == "policy_denied" else ("rate_limit" if isinstance(denial_reason, tuple) and denial_reason[0] == "quota" else "unauthorized"),
            "error_message": "Tool denied by policy" if denial_reason == "policy_denied" else ("Rate limit exceeded" if isinstance(denial_reason, tuple) and denial_reason[0] == "quota" else "Unauthorized"),
            "host_device_id": host_device_id,
            "duration_ms": int((time.time() - t0) * 1000),
            "normalized": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        }
        _append_execution(exec_row)
        if denial_reason == "policy_denied":
            return _err("UNAUTHORIZED" if False else "CONFLICT", "Tool denied by policy")  # will be mapped below
        if isinstance(denial_reason, tuple) and denial_reason[0] == "quota":
            return _err("RATE_LIMIT", "Quota exceeded", quota=denial_reason[1])
        return _err("UNAUTHORIZED", "Unauthorized")

    client, key, policy = chosen

    # Create execution queued -> running -> succeeded/failed
    exec_id = _new_exec_id()
    exec_row = {
        "id": exec_id,
        "client_id": client["id"],
        "api_key_id": key.get("id"),
        "tool_name": tool_name,
        "status": "queued",
        "request_params": {},
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": host_device_id,
        "duration_ms": None,
        "normalized": None,
        "created_at": now,
        "updated_at": now,
        "started_at": None,
        "finished_at": None
    }
    _append_execution(exec_row)

    # Transition to running
    exec_row["status"] = "running"
    exec_row["started_at"] = now
    exec_row["updated_at"] = now
    _save("tool_executions.json", executions)

    # "Execute" by toggling a server-side state file.
    state_path = os.path.join(_DB, "system_state.json")
    try:
        with open(state_path, encoding="utf-8") as f:
            state = json.load(f)
            if not isinstance(state, dict):
                state = {}
    except Exception:
        state = {}

    current = state.get("dark_mode")
    if current is None:
        current = False
    if not isinstance(current, bool):
        # Internal error - cannot interpret state
        exec_row["status"] = "failed"
        exec_row["error_type"] = "applescript_error"
        exec_row["error_message"] = "Appearance setting unavailable"
        exec_row["finished_at"] = now
        exec_row["updated_at"] = now
        exec_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_executions.json", executions)
        return _err("CONFLICT", "Appearance setting cannot be changed")

    state["dark_mode"] = (not current)
    try:
        with open(state_path, "w", encoding="utf-8") as f:
            json.dump(state, f, ensure_ascii=False, indent=2)
    except Exception:
        exec_row["status"] = "failed"
        exec_row["error_type"] = "applescript_error"
        exec_row["error_message"] = "Failed to persist appearance setting"
        exec_row["finished_at"] = now
        exec_row["updated_at"] = now
        exec_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_executions.json", executions)
        return _err("CONFLICT", "Appearance setting cannot be changed")

    result = {"mode": "dark" if state["dark_mode"] else "light"}

    exec_row["status"] = "succeeded"
    exec_row["result_data"] = result
    exec_row["finished_at"] = now
    exec_row["updated_at"] = now
    exec_row["duration_ms"] = int((time.time() - t0) * 1000)
    _save("tool_executions.json", executions)

    # Update api_key last_used_at
    key["last_used_at"] = now
    key["updated_at"] = now
    _save("api_keys.json", api_keys)

    return {"execution_id": exec_id, "tool_name": tool_name, "status": "succeeded", "result": result}

def system_get_battery_status(**_extra):
    import json, os, datetime, time, uuid, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    now_dt = datetime.datetime.utcnow()

    tool_name = "system_get_battery_status"

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    tool_policies = _load("tool_policies.json")
    quotas = _load("usage_quotas.json")
    executions = _load("tool_executions.json")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}
    usable_pairs = []
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now_dt:
            continue
        c = client_by_id.get(k.get("client_id"))
        if not c or c.get("status") != "active":
            continue
        usable_pairs.append((c, k))

    known_hosts = {e.get("host_device_id") for e in executions if isinstance(e, dict) and e.get("host_device_id")}
    if not known_hosts:
        return _err("UNAUTHORIZED", "No configured host identities available")
    host_device_id = sorted(known_hosts)[0]

    if not usable_pairs:
        return _err("UNAUTHORIZED", "No active, unexpired API key for an active client is available")

    def _policy_for(client_id, tool):
        for p in tool_policies:
            if isinstance(p, dict) and p.get("client_id") == client_id and p.get("tool_name") == tool and p.get("status") == "active":
                return p
        return None

    def _count_recent(client_id, tool, window_seconds, scope, scope_tool_name):
        cutoff = now_dt - datetime.timedelta(seconds=window_seconds)
        n = 0
        for e in executions:
            if not isinstance(e, dict) or e.get("client_id") != client_id:
                continue
            created = _parse_dt(e.get("created_at"))
            if created is None or created < cutoff:
                continue
            if scope == "all_tools":
                n += 1
            else:
                if e.get("tool_name") == scope_tool_name:
                    n += 1
        return n

    def _check_quota(client_id, tool):
        for q in quotas:
            if not isinstance(q, dict):
                continue
            if q.get("client_id") != client_id or q.get("status") != "active":
                continue
            scope = q.get("scope")
            w = q.get("window_seconds")
            m = q.get("max_requests")
            if not isinstance(w, int) or not isinstance(m, int):
                continue
            if scope == "all_tools":
                if q.get("tool_name") is not None:
                    continue
                if _count_recent(client_id, tool, w, "all_tools", None) + 1 > m:
                    return False, {"scope": "all_tools", "window_seconds": w, "max_requests": m}
            elif scope == "tool":
                if q.get("tool_name") != tool:
                    continue
                if _count_recent(client_id, tool, w, "tool", tool) + 1 > m:
                    return False, {"scope": "tool", "tool_name": tool, "window_seconds": w, "max_requests": m}
        return True, None

    chosen = None
    denial = None
    for c, k in usable_pairs:
        pol = _policy_for(c["id"], tool_name)
        if pol is None or pol.get("effect") != "allow":
            denial = "policy"
            continue
        okq, qinfo = _check_quota(c["id"], tool_name)
        if not okq:
            denial = ("quota", qinfo)
            continue
        chosen = (c, k)
        break

    def _new_exec_id():
        return "exec_" + uuid.uuid4().hex

    def _persist_exec(row):
        executions.append(row)
        _save("tool_executions.json", executions)

    if chosen is None:
        c, k = usable_pairs[0]
        err_type = "policy_denied" if denial == "policy" else "rate_limit"
        err_msg = "Tool denied by policy" if denial == "policy" else "Rate limit exceeded"
        row = {
            "id": _new_exec_id(),
            "client_id": c["id"],
            "api_key_id": k.get("id"),
            "tool_name": tool_name,
            "status": "failed",
            "request_params": {},
            "result_data": None,
            "error_type": err_type,
            "error_message": err_msg,
            "host_device_id": host_device_id,
            "duration_ms": int((time.time() - t0) * 1000),
            "normalized": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        }
        _persist_exec(row)
        if denial == "policy":
            return _err("CONFLICT", "Tool denied by policy")
        return _err("RATE_LIMIT", "Quota exceeded", quota=denial[1] if isinstance(denial, tuple) else None)

    client, key = chosen

    exec_id = _new_exec_id()
    row = {
        "id": exec_id,
        "client_id": client["id"],
        "api_key_id": key.get("id"),
        "tool_name": tool_name,
        "status": "queued",
        "request_params": {},
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": host_device_id,
        "duration_ms": None,
        "normalized": None,
        "created_at": now,
        "updated_at": now,
        "started_at": None,
        "finished_at": None
    }
    _persist_exec(row)

    row["status"] = "running"
    row["started_at"] = now
    row["updated_at"] = now
    _save("tool_executions.json", executions)

    # Read from server-side state or fallback to deterministic pseudo values.
    state_path = os.path.join(_DB, "system_state.json")
    try:
        with open(state_path, encoding="utf-8") as f:
            state = json.load(f)
            if not isinstance(state, dict):
                state = {}
    except Exception:
        state = {}

    battery = state.get("battery")
    if battery is None:
        # initialize if missing
        battery = {"level": 100, "charging": False}
        state["battery"] = battery
        try:
            with open(state_path, "w", encoding="utf-8") as f:
                json.dump(state, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

    if not isinstance(battery, dict) or "level" not in battery or "charging" not in battery:
        row["status"] = "failed"
        row["error_type"] = "applescript_error"
        row["error_message"] = "Battery data unavailable"
        row["finished_at"] = now
        row["updated_at"] = now
        row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_executions.json", executions)
        return _err("CONFLICT", "Battery status cannot be read")

    level = battery.get("level")
    charging = battery.get("charging")
    if not isinstance(level, int) or level < 0 or level > 100 or not isinstance(charging, bool):
        row["status"] = "failed"
        row["error_type"] = "applescript_error"
        row["error_message"] = "Battery data invalid"
        row["finished_at"] = now
        row["updated_at"] = now
        row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_executions.json", executions)
        return _err("CONFLICT", "Battery status cannot be read")

    result = {"level": level, "charging": charging}

    row["status"] = "succeeded"
    row["result_data"] = result
    row["finished_at"] = now
    row["updated_at"] = now
    row["duration_ms"] = int((time.time() - t0) * 1000)
    _save("tool_executions.json", executions)

    key["last_used_at"] = now
    key["updated_at"] = now
    _save("api_keys.json", api_keys)

    return {"execution_id": exec_id, "tool_name": tool_name, "status": "succeeded", "result": result}

def calendar_add(title, startDate, endDate, calendar=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "calendar_add"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00").astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _parse_local_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            return datetime.datetime.strptime(s.strip(), "%Y-%m-%d %H:%M:%S")
        except ValueError:
            return None

    def _get_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _extract_api_key_from_extra():
        for k in ("api_key", "apiKey", "key", "token", "authorization", "Authorization", "x_api_key", "x-api-key"):
            v = _extra.get(k)
            if isinstance(v, str) and v.strip():
                vv = v.strip()
                if vv.lower().startswith("bearer "):
                    vv = vv.split(" ", 1)[1].strip()
                return vv
        return None

    def _key_is_expired(key_row, now):
        exp = _parse_rfc3339(key_row.get("expires_at"))
        return exp is not None and exp <= now

    def _resolve_auth():
        """
        Ambient auth: if no key provided, pick any active, non-expired key whose client is active.
        If key provided: match against api_keys.id OR api_keys.key_prefix (client-visible).
        Never compare against key_hash.
        """
        now = _utcnow()
        api_keys = _get_rows(_load("api_keys.json"))
        api_clients = _get_rows(_load("api_clients.json"))

        clients_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}
        provided = _extract_api_key_from_extra()

        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if _key_is_expired(k, now):
                continue
            cli = clients_by_id.get(k.get("client_id"))
            if not isinstance(cli, dict) or cli.get("status") != "active":
                continue
            if provided:
                if provided == k.get("id") or provided == k.get("key_prefix"):
                    candidates.append((cli, k))
            else:
                candidates.append((cli, k))

        if not candidates:
            return None, None

        # Choose the one most recently used (or newest) to be stable.
        def _dt(s):
            d = _parse_rfc3339(s)
            return d or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        candidates.sort(key=lambda ck: (_dt(ck[1].get("last_used_at")), _dt(ck[1].get("created_at"))), reverse=True)
        return candidates[0][0], candidates[0][1]

    def _policy_for_client(client_id, tool):
        policies = _get_rows(_load("tool_policies.json"))
        for p in policies:
            if not isinstance(p, dict):
                continue
            if p.get("client_id") == client_id and p.get("tool_name") == tool and p.get("status") == "active":
                return p
        return None

    def _check_quota(client_id, tool):
        now = _utcnow()
        quotas = _get_rows(_load("usage_quotas.json"))
        execs = _get_rows(_load("tool_executions.json"))

        def _count_within(window_s, tool_scope):
            cutoff = now - datetime.timedelta(seconds=window_s)
            n = 0
            for e in execs:
                if not isinstance(e, dict):
                    continue
                if e.get("client_id") != client_id:
                    continue
                if tool_scope == "all_tools":
                    pass
                else:
                    if e.get("tool_name") != tool:
                        continue
                created = _parse_rfc3339(e.get("created_at"))
                if created is None:
                    continue
                if created >= cutoff:
                    n += 1
            return n

        # enforce both all_tools and tool quotas (active)
        applicable = []
        for q in quotas:
            if not isinstance(q, dict):
                continue
            if q.get("client_id") != client_id or q.get("status") != "active":
                continue
            if q.get("scope") == "all_tools":
                applicable.append(q)
            elif q.get("scope") == "tool" and q.get("tool_name") == tool:
                applicable.append(q)

        # If no quota rows, no enforcement.
        for q in applicable:
            ws = q.get("window_seconds")
            mr = q.get("max_requests")
            if not isinstance(ws, int) or not isinstance(mr, int):
                continue
            if ws < 1 or ws > 86400 or mr < 1 or mr > 100000:
                continue
            c = _count_within(ws, q.get("scope"))
            if c + 1 > mr:
                # compute retry-after seconds: until oldest within window falls out
                cutoff = now - datetime.timedelta(seconds=ws)
                oldest = None
                for e in execs:
                    if not isinstance(e, dict):
                        continue
                    if e.get("client_id") != client_id:
                        continue
                    if q.get("scope") == "tool" and e.get("tool_name") != tool:
                        continue
                    created = _parse_rfc3339(e.get("created_at"))
                    if created is None or created < cutoff:
                        continue
                    if oldest is None or created < oldest:
                        oldest = created
                retry_after = None
                if oldest is not None:
                    retry_after = int(max(0, (oldest + datetime.timedelta(seconds=ws) - now).total_seconds()))
                msg = f"Quota exceeded for scope={q.get('scope')} (window={ws}s, max={mr})."
                if retry_after is not None:
                    msg += f" Retry after {retry_after}s."
                return False, msg, {"scope": q.get("scope"), "tool_name": q.get("tool_name"), "window_seconds": ws, "max_requests": mr, "retry_after_seconds": retry_after}
        return True, None, None

    def _new_exec_id():
        return "asmc_exe_" + uuid.uuid4().hex[:26]

    def _pick_host_device_id():
        # Use any configured host_device_id present in existing executions.
        rows = _get_rows(_load("tool_executions.json"))
        for e in rows:
            if isinstance(e, dict):
                hid = e.get("host_device_id")
                if isinstance(hid, str) and hid.strip():
                    return hid.strip()
        # fallback deterministic placeholder if none exist
        return "00000000-0000-0000-0000-000000000000"

    def _append_execution(executions, row):
        executions.append(row)

    def _finalize_and_return(executions, api_keys_rows, api_key_row, status, result=None, error_type=None, error_message=None):
        now = _utcnow()
        # update key last_used_at on success only (status succeeded)
        if api_key_row is not None and status == "succeeded":
            for k in api_keys_rows:
                if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                    k["last_used_at"] = _iso(now)
                    k["updated_at"] = _iso(now)
                    break
            _save("api_keys.json", api_keys_rows)

        _save("tool_executions.json", executions)
        latency_ms = int((time.time() - t0) * 1000)

        if status == "succeeded":
            return {
                "execution_id": executions[-1]["id"],
                "tool_name": tool_name,
                "status": status,
                "duration_ms": latency_ms,
                "result": result if result is not None else {},
            }
        return _err("VALIDATION_ERROR" if error_type == "validation_error" else
                    "RATE_LIMIT" if error_type == "rate_limited" else
                    "CONFLICT" if error_type == "policy_denied" else
                    "UNAUTHORIZED" if error_type == "unauthorized" else
                    "CONFLICT",
                    error_message or "Request failed.",
                    execution_id=executions[-1]["id"],
                    tool_name=tool_name,
                    error_type=error_type)

    # ---- Authenticate (ambient) ----
    client, api_key = _resolve_auth()
    executions_store = _load("tool_executions.json")
    executions = _get_rows(executions_store)
    api_keys_rows = _get_rows(_load("api_keys.json"))

    now = _utcnow()
    exec_row = {
        "id": _new_exec_id(),
        "client_id": client.get("id") if client else None,
        "api_key_id": api_key.get("id") if api_key else None,
        "tool_name": tool_name,
        "status": "failed",
        "request_params": {},  # filled after defaulting/validation
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": _pick_host_device_id(),
        "duration_ms": None,
        "normalized": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
        "started_at": None,
        "finished_at": None,
    }

    if client is None or api_key is None:
        exec_row["error_type"] = "unauthorized"
        exec_row["error_message"] = "Missing/invalid/expired API key or inactive client"
        exec_row["finished_at"] = _iso(now)
        _append_execution(executions, exec_row)
        _save("tool_executions.json", executions)
        return _err("UNAUTHORIZED", exec_row["error_message"], execution_id=exec_row["id"], tool_name=tool_name)

    # ---- Validate params & defaults ----
    if calendar is None:
        calendar = "Calendar"

    effective = {"title": title, "startDate": startDate, "endDate": endDate, "calendar": calendar}
    exec_row["request_params"] = effective

    if not isinstance(title, str) or not title.strip():
        exec_row["error_type"] = "validation_error"
        exec_row["error_message"] = "title is required"
    elif not isinstance(startDate, str) or _parse_local_dt(startDate) is None:
        exec_row["error_type"] = "validation_error"
        exec_row["error_message"] = "startDate must be in YYYY-MM-DD HH:MM:SS format"
    elif not isinstance(endDate, str) or _parse_local_dt(endDate) is None:
        exec_row["error_type"] = "validation_error"
        exec_row["error_message"] = "endDate must be in YYYY-MM-DD HH:MM:SS format"
    elif not isinstance(calendar, str) or not calendar.strip():
        exec_row["error_type"] = "validation_error"
        exec_row["error_message"] = "calendar must be a non-empty string"
    else:
        sd = _parse_local_dt(startDate)
        ed = _parse_local_dt(endDate)
        if not (ed > sd):
            exec_row["error_type"] = "validation_error"
            exec_row["error_message"] = "endDate must be after startDate"

    # ---- Policy ----
    pol = _policy_for_client(client["id"], tool_name)
    if exec_row["error_type"] is None:
        if pol is None or pol.get("effect") != "allow":
            exec_row["error_type"] = "policy_denied"
            exec_row["error_message"] = f"Tool {tool_name} denied by policy for client {client['id']}."
    # ---- Quota ----
    if exec_row["error_type"] is None:
        ok, msg, _meta = _check_quota(client["id"], tool_name)
        if not ok:
            exec_row["error_type"] = "rate_limited"
            exec_row["error_message"] = msg

    if exec_row["error_type"] is not None:
        exec_row["status"] = "failed"
        exec_row["updated_at"] = _iso(now)
        exec_row["finished_at"] = _iso(now)
        _append_execution(executions, exec_row)
        _save("tool_executions.json", executions)
        # map to vendor-like code
        code = "VALIDATION_ERROR" if exec_row["error_type"] == "validation_error" else \
               "RATE_LIMIT" if exec_row["error_type"] == "rate_limited" else \
               "CONFLICT" if exec_row["error_type"] == "policy_denied" else "UNAUTHORIZED"
        return _err(code, exec_row["error_message"], execution_id=exec_row["id"], tool_name=tool_name)

    # ---- Execute (offline simulated) ----
    started = _utcnow()
    exec_row["status"] = "running"
    exec_row["started_at"] = _iso(started)
    exec_row["updated_at"] = _iso(started)
    _append_execution(executions, exec_row)
    _save("tool_executions.json", executions)

    # Simulate a created event object
    finished = _utcnow()
    duration_ms = int((finished - started).total_seconds() * 1000)
    result = {
        "id": "cal_evt_" + uuid.uuid4().hex[:18],
        "title": title.strip(),
        "calendar": calendar,
        "startDate": startDate,
        "endDate": endDate,
        "created": True,
    }

    # transition running -> succeeded
    executions[-1]["status"] = "succeeded"
    executions[-1]["result_data"] = result
    executions[-1]["duration_ms"] = max(0, duration_ms)
    executions[-1]["updated_at"] = _iso(finished)
    executions[-1]["finished_at"] = _iso(finished)

    # persist + last_used_at
    # update key last_used_at
    for k in api_keys_rows:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = _iso(finished)
            k["updated_at"] = _iso(finished)
            break
    _save("api_keys.json", api_keys_rows)
    _save("tool_executions.json", executions)

    return {
        "execution_id": executions[-1]["id"],
        "tool_name": tool_name,
        "status": "succeeded",
        "duration_ms": executions[-1]["duration_ms"],
        "event": result,
    }

def calendar_list(calendar=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
