            "updated_at": _iso(now),
            "started_at": None,
            "finished_at": _iso(now),
        }
        executions.append(exec_row)
        _save("tool_executions.json", executions)
        return _err("VALIDATION_ERROR", exec_row["error_message"], execution_id=exec_row["id"], tool_name=tool_name)

    client, api_key = _resolve_auth()
    executions = _get_rows(_load("tool_executions.json"))
    api_keys_rows = _get_rows(_load("api_keys.json"))
    now = _utcnow()

    exec_row = {
        "id": _new_exec_id(),
        "client_id": client.get("id") if client else None,
        "api_key_id": api_key.get("id") if api_key else None,
        "tool_name": tool_name,
        "status": "failed",
        "request_params": {"calendar": calendar} if calendar is not None else {},
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": _pick_host_device_id(),
        "duration_ms": None,
        "normalized": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
        "started_at": None,
        "finished_at": None,
    }

