        exec_row["error_type"] = "unauthorized"
        exec_row["error_message"] = "Missing/invalid/expired API key or inactive client"
        exec_row["finished_at"] = _iso(now)
        executions.append(exec_row)
        _save("tool_executions.json", executions)
        return _err("UNAUTHORIZED", exec_row["error_message"], execution_id=exec_row["id"], tool_name=tool_name)

    pol = _policy_for_client(client["id"], tool_name)
    if pol is None or pol.get("effect") != "allow":
        exec_row["error_type"] = "policy_denied"
        exec_row["error_message"] = f"Tool {tool_name} denied by policy for client {client['id']}."
        exec_row["finished_at"] = _iso(now)
        executions.append(exec_row)
        _save("tool_executions.json", executions)
        return _err("CONFLICT", exec_row["error_message"], execution_id=exec_row["id"], tool_name=tool_name)

    ok, msg = _check_quota(client["id"], tool_name)
    if not ok:
        exec_row["error_type"] = "rate_limited"
        exec_row["error_message"] = msg
        exec_row["finished_at"] = _iso(now)
        executions.append(exec_row)
        _save("tool_executions.json", executions)
        return _err("RATE_LIMIT", msg, execution_id=exec_row["id"], tool_name=tool_name)

    # running -> succeeded (read)
    started = _utcnow()
    exec_row["status"] = "running"
    exec_row["started_at"] = _iso(started)
    exec_row["updated_at"] = _iso(started)
    executions.append(exec_row)
    _save("tool_executions.json", executions)

    # Offline: list is derived from prior calendar_add succeeded executions as "today".
    today = started.astimezone(datetime.timezone.utc).date()
    events = []
    for e in executions:
        if not isinstance(e, dict):
            continue
        if e.get("client_id") != client["id"]:
            continue
        if e.get("tool_name") != "calendar_add":
            continue
        if e.get("status") != "succeeded":
            continue
        rp = e.get("request_params") or {}
        if not isinstance(rp, dict):
            continue
        if calendar is not None and rp.get("calendar") != calendar:
            continue
        # interpret startDate in local format without timezone; compare date portion
        sd = rp.get("startDate")
        if isinstance(sd, str) and len(sd) >= 10:
            try:
                d = datetime.datetime.strptime(sd[:19], "%Y-%m-%d %H:%M:%S").date()
            except ValueError:
                continue
            if d != today:
                continue
        else:
            continue
        rd = e.get("result_data")
        if isinstance(rd, dict):
            events.append(rd)
        else:
            # minimal derived event
            events.append({
                "id": e.get("id"),
                "title": rp.get("title"),
                "calendar": rp.get("calendar"),
                "startDate": rp.get("startDate"),
                "endDate": rp.get("endDate"),
            })

    finished = _utcnow()
    duration_ms = int((finished - started).total_seconds() * 1000)
    executions[-1]["status"] = "succeeded"
    executions[-1]["result_data"] = {"events": events}
    executions[-1]["duration_ms"] = max(0, duration_ms)
    executions[-1]["updated_at"] = _iso(finished)
    executions[-1]["finished_at"] = _iso(finished)

    for k in api_keys_rows:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = _iso(finished)
            k["updated_at"] = _iso(finished)
            break
    _save("api_keys.json", api_keys_rows)
    _save("tool_executions.json", executions)

    return {
        "execution_id": executions[-1]["id"],
        "tool_name": tool_name,
        "status": "succeeded",
        "duration_ms": executions[-1]["duration_ms"],
        "events": events,
        "count": len(events),
    }

