    def _choose_auth():
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        now_dt = _parse_dt(now)
        c_by_id = {c.get("id"): c for c in clients if isinstance(c, dict) and isinstance(c.get("id"), str)}
        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            if not isinstance(cid, str) or cid not in c_by_id:
                continue
            c = c_by_id[cid]
            if c.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and now_dt is not None and exp <= now_dt:
                continue
            candidates.append((c, k))
        if not candidates:
            return None, None
        def key_sort(pair):
            k = pair[1]
            lu = _parse_dt(k.get("last_used_at"))
            return (lu is not None, lu or datetime.datetime.min)
        candidates.sort(key=key_sort, reverse=True)
        return candidates[0][0], candidates[0][1]

    def _policy_for(client_id):
        policies = _load("tool_policies.json")
        best = None
        for p in policies:
            if not isinstance(p, dict):
                continue
            if p.get("client_id") == client_id and p.get("tool_name") == TOOL_NAME:
                if p.get("status") == "active":
                    best = p
                    break
                if best is None:
                    best = p
        return best

    def _count_in_window(client_id, tool_name, window_seconds, scope):
        execs = _load("tool_executions.json")
        now_dt = _parse_dt(now)
        if now_dt is None:
            return 0
        cutoff = now_dt - datetime.timedelta(seconds=window_seconds)
        n = 0
        for e in execs:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id:
                continue
            if scope == "tool" and e.get("tool_name") != tool_name:
                continue
            created = _parse_dt(e.get("created_at"))
            if created is None:
                continue
            if created >= cutoff:
                n += 1
        return n

    def _enforce_quotas_or_error(client_id):
        quotas = _load("usage_quotas.json")
        active = []
        for q in quotas:
            if not isinstance(q, dict):
                continue
            if q.get("client_id") != client_id:
                continue
            if q.get("status") != "active":
                continue
            scope = q.get("scope")
            if scope == "all_tools":
                if q.get("tool_name") is not None:
                    continue
                active.append(q)
            elif scope == "tool":
                if q.get("tool_name") != TOOL_NAME:
                    continue
                active.append(q)
        for q in active:
            ws = q.get("window_seconds")
            mx = q.get("max_requests")
            if not isinstance(ws, int) or not isinstance(mx, int):
                continue
            if ws < 1 or ws > 86400 or mx < 1 or mx > 100000:
                continue
            scope = q.get("scope")
            used = _count_in_window(client_id, TOOL_NAME, ws, scope)
            if used + 1 > mx:
                return _err("QUOTA_EXCEEDED", "Quota exceeded for tool execution window.", quota_id=q.get("id"), window_seconds=ws, max_requests=mx)
        return None

    def _log_exec(client_id, api_key_id, status, request_params, result_data=None, error_type=None, error_message=None, started_at=None, finished_at=None, duration_ms=None):
        execs = _load("tool_executions.json")
        host_id = _ensure_host_id()
        row = {
            "id": _gen_id("exec"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": TOOL_NAME,
            "status": status,
            "request_params": request_params,
            "result_data": result_data,
            "error_type": error_type,
            "error_message": error_message,
            "host_device_id": host_id,
            "duration_ms": duration_ms,
            "normalized": None,
            "created_at": now,
            "updated_at": now,
            "started_at": started_at,
            "finished_at": finished_at,
        }
        execs.append(row)
        _save("tool_executions.json", execs)
        return row

    # authenticate
    client, key = _choose_auth()
    if client is None or key is None:
        _log_exec("unknown", None, "failed", {}, error_type="unauthorized", error_message="No active API key / client available for authentication.", finished_at=now, duration_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "No active API key / client available for authentication.")
    client_id = client["id"]
    api_key_id = key["id"]

    request_params = {}  # no parameters

    # host identity check
    host_id = _ensure_host_id()
    configured_hosts = []
    for e in _load("tool_executions.json"):
        hid = e.get("host_device_id") if isinstance(e, dict) else None
        if isinstance(hid, str) and hid and hid not in configured_hosts:
            configured_hosts.append(hid)
    if configured_hosts and host_id not in configured_hosts:
        _log_exec(client_id, api_key_id, "failed", request_params, error_type="host_mismatch", error_message="host_device_id mismatch.", finished_at=now, duration_ms=int((time.time() - t0) * 1000))
        return _err("VALIDATION_ERROR", "host_device_id mismatch.")

    # policy (default deny)
    pol = _policy_for(client_id)
    if not pol or pol.get("status") != "active" or pol.get("effect") != "allow":
        _log_exec(client_id, api_key_id, "failed", request_params, error_type="policy_denied", error_message="Tool denied by policy.", finished_at=now, duration_ms=int((time.time() - t0) * 1000))
        return _err("UNAUTHORIZED", "Tool not permitted by policy.")

    # quota
    qerr = _enforce_quotas_or_error(client_id)
    if qerr:
        _log_exec(client_id, api_key_id, "failed", request_params, error_type="quota_exceeded", error_message=qerr["error"]["message"], finished_at=now, duration_ms=int((time.time() - t0) * 1000))
        return qerr

    # execute: simulate Focus toggle with persisted state and permission gate
    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    state_path = os.path.join(_DB, "system_focus_state.json")
    try:
        # permission state: if file exists and says not granted => forbidden
        perm_path = os.path.join(_DB, "host_permissions.json")
        perms = None
        try:
            with open(perm_path, encoding="utf-8") as f:
                perms = json.load(f)
        except Exception:
            perms = None
        if isinstance(perms, dict):
            if perms.get("accessibility_granted") is False or perms.get("automation_granted") is False:
                finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _log_exec(client_id, api_key_id, "failed", request_params, error_type="policy_denied", error_message="Host permissions not granted for automation/accessibility.", started_at=started, finished_at=finished, duration_ms=int((time.time() - t0) * 1000))
                return _err("UNAUTHORIZED", "Host permissions not granted for automation/accessibility.")
            if perms.get("notifications_controls_blocked") is True:
                finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _log_exec(client_id, api_key_id, "failed", request_params, error_type="policy_denied", error_message="Notification controls blocked by host policy.", started_at=started, finished_at=finished, duration_ms=int((time.time() - t0) * 1000))
                return _err("UNAUTHORIZED", "Notification controls blocked by host policy.")

        # load current state
        cur = {"enabled": False}
        try:
            with open(state_path, encoding="utf-8") as f:
                cur = json.load(f)
        except Exception:
            cur = {"enabled": False}

        if not isinstance(cur, dict) or "enabled" not in cur or not isinstance(cur.get("enabled"), bool):
            # bad system state
            finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            _log_exec(client_id, api_key_id, "failed", request_params, error_type="applescript_error", error_message="Invalid focus state store.", started_at=started, finished_at=finished, duration_ms=int((time.time() - t0) * 1000))
            return _err("CONFLICT", "Cannot toggle Do Not Disturb in current state.")

        new_enabled = not cur["enabled"]
        new_state = {"enabled": new_enabled, "updated_at": started}
        with open(state_path, "w", encoding="utf-8") as f:
            json.dump(new_state, f, ensure_ascii=False, indent=2)

    except OSError as e:
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _log_exec(client_id, api_key_id, "failed", request_params, error_type="applescript_error", error_message=str(e), started_at=started, finished_at=finished, duration_ms=int((time.time() - t0) * 1000))
        return _err("CONFLICT", "Toggle failed.", detail=str(e))

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    result = {"do_not_disturb_enabled": new_enabled, "action": "enabled" if new_enabled else "disabled"}

    exec_row = _log_exec(client_id, api_key_id, "succeeded", request_params, result_data=result, started_at=started, finished_at=finished, duration_ms=int((time.time() - t0) * 1000))

    # update last_used_at on success
    keys = _load("api_keys.json")
    changed = False
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = finished
            k["updated_at"] = finished
            changed = True
            break
    if changed:
        _save("api_keys.json", keys)

    return {"execution": exec_row, "result": result}

