    result = {"delivered": True, "notification": {"id": notif["id"], "title": title, "message": message, "sound": sound_eff}}

    exec_row = _log_exec(
        client_id,
        api_key_id,
        "succeeded",
        request_params,
        result_data=result,
        started_at=started,
        finished_at=finished,
