            k["last_used_at"] = finished
            k["updated_at"] = finished
            changed = True
            break
    if changed:
        _save("api_keys.json", keys)

    return {"execution": exec_row, "result": result}

def iterm_paste_clipboard(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "iterm_paste_clipboard"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00").astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _get_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _extract_api_key_from_extra():
        for k in ("api_key", "apiKey", "key", "token", "authorization", "Authorization", "x_api_key", "x-api-key"):
            v = _extra.get(k)
            if isinstance(v, str) and v.strip():
                vv = v.strip()
                if vv.lower().startswith("bearer "):
                    vv = vv.split(" ", 1)[1].strip()
                return vv
        return None

    def _key_is_expired(key_row, now):
        exp = _parse_rfc3339(key_row.get("expires_at"))
        return exp is not None and exp <= now

    def _resolve_auth():
        now = _utcnow()
        api_keys = _get_rows(_load("api_keys.json"))
        api_clients = _get_rows(_load("api_clients.json"))
        clients_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}
        provided = _extract_api_key_from_extra()

        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if _key_is_expired(k, now):
                continue
            cli = clients_by_id.get(k.get("client_id"))
            if not isinstance(cli, dict) or cli.get("status") != "active":
                continue
            if provided:
                if provided == k.get("id") or provided == k.get("key_prefix"):
                    candidates.append((cli, k))
            else:
                candidates.append((cli, k))

        if not candidates:
            return None, None

        def _dt(s):
            d = _parse_rfc3339(s)
            return d or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        candidates.sort(key=lambda ck: (_dt(ck[1].get("last_used_at")), _dt(ck[1].get("created_at"))), reverse=True)
        return candidates[0][0], candidates[0][1]

    def _policy_for_client(client_id, tool):
        policies = _get_rows(_load("tool_policies.json"))
        for p in policies:
            if not isinstance(p, dict):
                continue
            if p.get("client_id") == client_id and p.get("tool_name") == tool and p.get("status") == "active":
                return p
        return None

    def _check_quota(client_id, tool):
        now = _utcnow()
        quotas = _get_rows(_load("usage_quotas.json"))
        execs = _get_rows(_load("tool_executions.json"))

        def _count_within(window_s, scope):
            cutoff = now - datetime.timedelta(seconds=window_s)
            n = 0
            for e in execs:
                if not isinstance(e, dict):
                    continue
                if e.get("client_id") != client_id:
                    continue
                if scope == "tool" and e.get("tool_name") != tool:
                    continue
                created = _parse_rfc3339(e.get("created_at"))
                if created and created >= cutoff:
                    n += 1
            return n

        applicable = []
        for q in quotas:
            if not isinstance(q, dict):
                continue
            if q.get("client_id") != client_id or q.get("status") != "active":
                continue
            if q.get("scope") == "all_tools":
                applicable.append(q)
            elif q.get("scope") == "tool" and q.get("tool_name") == tool:
                applicable.append(q)

        for q in applicable:
            ws = q.get("window_seconds")
            mr = q.get("max_requests")
            if not isinstance(ws, int) or not isinstance(mr, int):
                continue
            c = _count_within(ws, q.get("scope"))
            if c + 1 > mr:
                msg = f"Quota exceeded for scope={q.get('scope')} (window={ws}s, max={mr})."
                return False, msg
        return True, None

    def _new_exec_id():
        return "asmc_exe_" + uuid.uuid4().hex[:26]

    def _pick_host_device_id():
        rows = _get_rows(_load("tool_executions.json"))
        for e in rows:
            if isinstance(e, dict):
                hid = e.get("host_device_id")
                if isinstance(hid, str) and hid.strip():
                    return hid.strip()
        return "00000000-0000-0000-0000-000000000000"

    client, api_key = _resolve_auth()
    executions = _get_rows(_load("tool_executions.json"))
    api_keys_rows = _get_rows(_load("api_keys.json"))
    now = _utcnow()

    exec_row = {
        "id": _new_exec_id(),
        "client_id": client.get("id") if client else None,
        "api_key_id": api_key.get("id") if api_key else None,
        "tool_name": tool_name,
        "status": "failed",
        "request_params": {},
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": _pick_host_device_id(),
        "duration_ms": None,
        "normalized": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
        "started_at": None,
        "finished_at": None,
    }

    if client is None or api_key is None:
        exec_row["error_type"] = "unauthorized"
        exec_row["error_message"] = "Missing/invalid/expired API key or inactive client"

    if exec_row["error_type"] is None:
        pol = _policy_for_client(client["id"], tool_name)
        if pol is None or pol.get("effect") != "allow":
            exec_row["error_type"] = "policy_denied"
            exec_row["error_message"] = f"Tool {tool_name} denied by policy for client {client['id']}."

    if exec_row["error_type"] is None:
        ok, msg = _check_quota(client["id"], tool_name)
        if not ok:
            exec_row["error_type"] = "rate_limited"
            exec_row["error_message"] = msg

    if exec_row["error_type"] is not None:
        exec_row["status"] = "failed"
        exec_row["finished_at"] = _iso(now)
        executions.append(exec_row)
        _save("tool_executions.json", executions)
        code = "RATE_LIMIT" if exec_row["error_type"] == "rate_limited" else \
               "CONFLICT" if exec_row["error_type"] == "policy_denied" else "UNAUTHORIZED"
        return _err(code, exec_row["error_message"], execution_id=exec_row["id"], tool_name=tool_name)

    started = _utcnow()
    exec_row["status"] = "running"
    exec_row["started_at"] = _iso(started)
    exec_row["updated_at"] = _iso(started)
    executions.append(exec_row)
    _save("tool_executions.json", executions)

    finished = _utcnow()
    duration_ms = int((finished - started).total_seconds() * 1000)
    result = {"pasted": True}

    executions[-1]["status"] = "succeeded"
    executions[-1]["result_data"] = result
    executions[-1]["duration_ms"] = max(0, duration_ms)
    executions[-1]["updated_at"] = _iso(finished)
    executions[-1]["finished_at"] = _iso(finished)

    for k in api_keys_rows:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = _iso(finished)
            k["updated_at"] = _iso(finished)
            break
    _save("api_keys.json", api_keys_rows)
    _save("tool_executions.json", executions)

    return {
        "execution_id": executions[-1]["id"],
        "tool_name": tool_name,
        "status": "succeeded",
        "duration_ms": executions[-1]["duration_ms"],
        "pasted": True,
    }

