def mail_create_email(recipient, subject, body, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "mail_create_email"
    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    policies = _load("tool_policies.json")
    execs = _load("tool_executions.json")
    quotas = _load("usage_quotas.json")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _is_key_valid(krow, crow):
        if crow.get("status") != "active":
            return False
        if krow.get("status") != "active":
            return False
        exp = _parse_dt(krow.get("expires_at"))
        if exp is not None and exp <= datetime.datetime.utcnow():
            return False
        return True

    def _policy_for(client_id):
        for p in policies:
            if p.get("client_id") == client_id and p.get("tool_name") == TOOL and p.get("status") == "active":
                return p
        return None

    allowed_hosts = []
    env_hosts = os.environ.get("HOST_DEVICE_IDS") or os.environ.get("HOST_DEVICE_ID")
    if env_hosts:
        allowed_hosts = [h.strip() for h in env_hosts.split(",") if h.strip()]
    host_device_id = os.environ.get("HOST_DEVICE_ID") or (allowed_hosts[0] if allowed_hosts else "host_local_default")
    def _host_ok():
        if allowed_hosts:
            return host_device_id in allowed_hosts
        return True

    chosen = None
    for k in keys:
        c = next((x for x in clients if x.get("id") == k.get("client_id")), None)
        if not c or not _is_key_valid(k, c):
            continue
        pol = _policy_for(c.get("id"))
        if not pol or pol.get("effect") != "allow":
            continue
        if not _host_ok():
            continue
        chosen = (c, k, pol)
        break

    effective_params = {"recipient": recipient, "subject": subject, "body": body}

    def _append_failed_execution(client_id, api_key_id, error_type, error_message):
        exec_id = "exec_" + uuid.uuid4().hex
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        duration_ms = int((time.time() - t0) * 1000)
        row = {
            "id": exec_id,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": TOOL,
            "status": "failed",
            "request_params": effective_params,
            "result_data": None,
            "error_type": error_type,
            "error_message": error_message,
            "host_device_id": host_device_id,
            "duration_ms": duration_ms,
            "normalized": {"recipient": recipient, "subject": subject} if isinstance(recipient, str) else None,
            "created_at": ts,
            "updated_at": ts,
            "started_at": ts,
            "finished_at": ts
        }
        execs.append(row)
        _save("tool_executions.json", execs)
        return exec_id

    if not chosen:
        any_valid = None
        for k in keys:
            c = next((x for x in clients if x.get("id") == k.get("client_id")), None)
            if c and _is_key_valid(k, c):
                any_valid = (c, k)
                break
        if any_valid:
            c, k = any_valid
            if not _host_ok():
                exec_id = _append_failed_execution(c.get("id"), k.get("id"), "unauthorized", "host_device_id is not recognized by server configuration.")
                return _err("UNAUTHORIZED", "host_device_id is not recognized by server configuration.", execution_id=exec_id)
            exec_id = _append_failed_execution(c.get("id"), k.get("id"), "policy_denied", "Tool is not allowed by policy.")
            return _err("UNAUTHORIZED", "Client is not authorized to invoke this tool.", execution_id=exec_id)
        exec_id = _append_failed_execution("unknown", None, "unauthorized", "No active, non-expired API key for any active client is available.")
        return _err("UNAUTHORIZED", "No authenticated context available.", execution_id=exec_id)

    client, key, policy = chosen

    # Validate inputs
    if not isinstance(recipient, str) or not recipient.strip():
        exec_id = _append_failed_execution(client.get("id"), key.get("id"), "validation_error", "recipient is required and must be a non-empty string.")
        return _err("VALIDATION_ERROR", "recipient is required and must be a non-empty string.", execution_id=exec_id)
    if not isinstance(subject, str) or not subject.strip():
        exec_id = _append_failed_execution(client.get("id"), key.get("id"), "validation_error", "subject is required and must be a non-empty string.")
        return _err("VALIDATION_ERROR", "subject is required and must be a non-empty string.", execution_id=exec_id)
    if not isinstance(body, str) or not body.strip():
        exec_id = _append_failed_execution(client.get("id"), key.get("id"), "validation_error", "body is required and must be a non-empty string.")
        return _err("VALIDATION_ERROR", "body is required and must be a non-empty string.", execution_id=exec_id)

    # Basic email format validation
    if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", recipient.strip()):
        exec_id = _append_failed_execution(client.get("id"), key.get("id"), "validation_error", "recipient must be a valid email address format.")
        return _err("VALIDATION_ERROR", "recipient must be a valid email address format.", execution_id=exec_id)

    # Quota enforcement
    def _within_window(created_at_str, window_seconds):
        dt = _parse_dt(created_at_str)
        if dt is None:
            return False
        return (datetime.datetime.utcnow() - dt).total_seconds() <= window_seconds

    active_quotas = [q for q in quotas if q.get("client_id") == client.get("id") and q.get("status") == "active"]
    for q in active_quotas:
        scope = q.get("scope")
        ws = q.get("window_seconds")
        mx = q.get("max_requests")
        if not isinstance(ws, int) or not (1 <= ws <= 86400):
            continue
        if not isinstance(mx, int) or not (1 <= mx <= 100000):
            continue
        if scope == "all_tools" and q.get("tool_name") is None:
            recent = sum(1 for e in execs if e.get("client_id") == client.get("id") and _within_window(e.get("created_at"), ws))
            if recent + 1 > mx:
                exec_id = _append_failed_execution(client.get("id"), key.get("id"), "rate_limited", "Quota exceeded for this client.")
                return _err("RATE_LIMIT", "Rate limit exceeded.", execution_id=exec_id, quota=q)
        if scope == "tool" and q.get("tool_name") == TOOL:
            recent = sum(1 for e in execs if e.get("client_id") == client.get("id") and e.get("tool_name") == TOOL and _within_window(e.get("created_at"), ws))
            if recent + 1 > mx:
                exec_id = _append_failed_execution(client.get("id"), key.get("id"), "rate_limited", "Quota exceeded for this client.")
                return _err("RATE_LIMIT", "Rate limit exceeded.", execution_id=exec_id, quota=q)

    # Execute (offline): create a draft "id"
    exec_id = "exec_" + uuid.uuid4().hex
    created = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    row = {
        "id": exec_id,
