        "status": row["status"],
        "result": row["result_data"]
    }

def mail_list_emails(mailbox=None, account=None, count=None, unreadOnly=None, **_extra):
    import json, os, datetime, time, uuid, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "mail_list_emails"
    t0 = time.time()

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    policies = _load("tool_policies.json")
    execs = _load("tool_executions.json")
    quotas = _load("usage_quotas.json")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _isoz(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _is_key_valid(krow, crow):
        if crow.get("status") != "active":
            return False
        if krow.get("status") != "active":
            return False
        exp = _parse_dt(krow.get("expires_at"))
        if exp is not None and exp <= datetime.datetime.utcnow():
            return False
        return True

    def _policy_for(client_id):
        for p in policies:
            if p.get("client_id") == client_id and p.get("tool_name") == TOOL and p.get("status") == "active":
                return p
        return None

    allowed_hosts = []
    env_hosts = os.environ.get("HOST_DEVICE_IDS") or os.environ.get("HOST_DEVICE_ID")
    if env_hosts:
        allowed_hosts = [h.strip() for h in env_hosts.split(",") if h.strip()]
    host_device_id = os.environ.get("HOST_DEVICE_ID") or (allowed_hosts[0] if allowed_hosts else "host_local_default")
    def _host_ok():
        if allowed_hosts:
            return host_device_id in allowed_hosts
        return True

    chosen = None
    for k in keys:
        c = next((x for x in clients if x.get("id") == k.get("client_id")), None)
        if not c or not _is_key_valid(k, c):
            continue
        pol = _policy_for(c.get("id"))
        if not pol or pol.get("effect") != "allow":
            continue
        if not _host_ok():
            continue
        chosen = (c, k, pol)
        break

    # Defaults
    if mailbox is None:
        mailbox = "Inbox"
    if account is None:
        account = "iCloud"
    if count is None:
        count = 10

    effective_params = {"mailbox": mailbox, "account": account, "count": count}
    if unreadOnly is not None:
        effective_params["unreadOnly"] = unreadOnly

    def _append_failed_execution(client_id, api_key_id, error_type, error_message):
        exec_id = "exec_" + uuid.uuid4().hex
        ts = _isoz(datetime.datetime.utcnow())
        duration_ms = int((time.time() - t0) * 1000)
        row = {
            "id": exec_id,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": TOOL,
            "status": "failed",
            "request_params": effective_params,
            "result_data": None,
            "error_type": error_type,
            "error_message": error_message,
            "host_device_id": host_device_id,
            "duration_ms": duration_ms,
            "normalized": {"mailbox": mailbox, "account": account},
            "created_at": ts,
            "updated_at": ts,
            "started_at": ts,
            "finished_at": ts
        }
        execs.append(row)
        _save("tool_executions.json", execs)
        return exec_id

    if not chosen:
        any_valid = None
        for k in keys:
            c = next((x for x in clients if x.get("id") == k.get("client_id")), None)
            if c and _is_key_valid(k, c):
                any_valid = (c, k)
                break
        if any_valid:
            c, k = any_valid
            if not _host_ok():
                exec_id = _append_failed_execution(c.get("id"), k.get("id"), "unauthorized", "host_device_id is not recognized by server configuration.")
                return _err("UNAUTHORIZED", "host_device_id is not recognized by server configuration.", execution_id=exec_id)
            exec_id = _append_failed_execution(c.get("id"), k.get("id"), "policy_denied", "Tool is not allowed by policy.")
            return _err("UNAUTHORIZED", "Client is not authorized to invoke this tool.", execution_id=exec_id)
        exec_id = _append_failed_execution("unknown", None, "unauthorized", "No active, non-expired API key for any active client is available.")
        return _err("UNAUTHORIZED", "No authenticated context available.", execution_id=exec_id)

    client, key, policy = chosen

    # Parameter validation
    if not isinstance(mailbox, str) or not mailbox.strip():
        exec_id = _append_failed_execution(client.get("id"), key.get("id"), "validation_error", "mailbox must be a non-empty string.")
        return _err("VALIDATION_ERROR", "mailbox must be a non-empty string.", execution_id=exec_id)

    if not isinstance(account, str) or not account.strip():
        exec_id = _append_failed_execution(client.get("id"), key.get("id"), "validation_error", "account must be a non-empty string.")
        return _err("VALIDATION_ERROR", "account must be a non-empty string.", execution_id=exec_id)

    # count must be integer-like and 1..100 (tool_executions constraints)
    try:
        if isinstance(count, bool):
            raise ValueError()
        if isinstance(count, (int, float)):
            count_int = int(count)
            if float(count) != float(count_int):
                raise ValueError()
        else:
            raise ValueError()
    except Exception:
        exec_id = _append_failed_execution(client.get("id"), key.get("id"), "validation_error", "count must be an integer between 1 and 100.")
        return _err("VALIDATION_ERROR", "count must be an integer between 1 and 100.", execution_id=exec_id)

    if not (1 <= count_int <= 100):
        exec_id = _append_failed_execution(client.get("id"), key.get("id"), "validation_error", "count must be between 1 and 100.")
        return _err("VALIDATION_ERROR", "count must be between 1 and 100.", execution_id=exec_id)

    if unreadOnly is not None and not isinstance(unreadOnly, bool):
        exec_id = _append_failed_execution(client.get("id"), key.get("id"), "validation_error", "unreadOnly must be a boolean when provided.")
        return _err("VALIDATION_ERROR", "unreadOnly must be a boolean when provided.", execution_id=exec_id)

    # Policy parameter constraints: count_max
    pc = policy.get("parameter_constraints") if isinstance(policy, dict) else None
    if isinstance(pc, dict) and "count_max" in pc and pc["count_max"] is not None:
        cm = pc["count_max"]
        if isinstance(cm, int):
            if not (1 <= cm <= 100):
                exec_id = _append_failed_execution(client.get("id"), key.get("id"), "validation_error", "Policy count_max is invalid.")
                return _err("VALIDATION_ERROR", "Policy constraints invalid.", execution_id=exec_id)
            if count_int > cm:
                exec_id = _append_failed_execution(client.get("id"), key.get("id"), "policy_denied", "Requested count exceeds policy maximum.")
                return _err("UNAUTHORIZED", "Requested count exceeds policy maximum.", execution_id=exec_id)

    # Quota enforcement
    def _within_window(created_at_str, window_seconds):
        dt = _parse_dt(created_at_str)
        if dt is None:
            return False
        return (datetime.datetime.utcnow() - dt).total_seconds() <= window_seconds

    active_quotas = [q for q in quotas if q.get("client_id") == client.get("id") and q.get("status") == "active"]
    for q in active_quotas:
        scope = q.get("scope")
        ws = q.get("window_seconds")
        mx = q.get("max_requests")
        if not isinstance(ws, int) or not (1 <= ws <= 86400):
            continue
        if not isinstance(mx, int) or not (1 <= mx <= 100000):
            continue
        if scope == "all_tools" and q.get("tool_name") is None:
            recent = sum(1 for e in execs if e.get("client_id") == client.get("id") and _within_window(e.get("created_at"), ws))
            if recent + 1 > mx:
                exec_id = _append_failed_execution(client.get("id"), key.get("id"), "rate_limited", "Quota exceeded for this client.")
                return _err("RATE_LIMIT", "Rate limit exceeded.", execution_id=exec_id, quota=q)
        if scope == "tool" and q.get("tool_name") == TOOL:
            recent = sum(1 for e in execs if e.get("client_id") == client.get("id") and e.get("tool_name") == TOOL and _within_window(e.get("created_at"), ws))
            if recent + 1 > mx:
                exec_id = _append_failed_execution(client.get("id"), key.get("id"), "rate_limited", "Quota exceeded for this client.")
                return _err("RATE_LIMIT", "Rate limit exceeded.", execution_id=exec_id, quota=q)

    # Create execution
    exec_id = "exec_" + uuid.uuid4().hex
    created = _isoz(datetime.datetime.utcnow())
    row = {
        "id": exec_id,
        "client_id": client.get("id"),
        "api_key_id": key.get("id"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": {"mailbox": mailbox, "account": account, "count": count_int, **({"unreadOnly": unreadOnly} if unreadOnly is not None else {})},
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": host_device_id,
        "duration_ms": None,
        "normalized": {"mailbox": mailbox, "account": account},
        "created_at": created,
        "updated_at": created,
        "started_at": None,
        "finished_at": None
    }
    execs.append(row)

    transitions = {
        "queued": ["running", "cancelled", "failed"],
        "running": ["succeeded", "failed", "cancelled"],
        "succeeded": [],
        "failed": [],
        "cancelled": []
    }

    started = _isoz(datetime.datetime.utcnow())
    if "running" not in transitions.get(row["status"], []):
        fin = started
        row["status"] = "failed"
        row["error_type"] = "invalid_transition"
        row["error_message"] = "Invalid lifecycle transition."
        row["started_at"] = started
        row["finished_at"] = fin
        row["updated_at"] = fin
        row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_executions.json", execs)
        return _err("INVALID_TRANSITION", "Invalid execution status transition.", execution_id=exec_id)

    row["status"] = "running"
    row["started_at"] = started
    row["updated_at"] = started

    if os.environ.get("MAIL_INSTALLED") == "0":
        fin = _isoz(datetime.datetime.utcnow())
        row["status"] = "failed"
        row["error_type"] = "not_found"
        row["error_message"] = "Mail.app is not installed or cannot be launched."
        row["finished_at"] = fin
        row["updated_at"] = fin
        row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_executions.json", execs)
        return _err("NOT_FOUND", row["error_message"], execution_id=exec_id)

    if os.environ.get("AUTOMATION_ALLOWED_MAIL") == "0":
        fin = _isoz(datetime.datetime.utcnow())
        row["status"] = "failed"
        row["error_type"] = "policy_denied"
        row["error_message"] = "Mail automation permission denied."
        row["finished_at"] = fin
        row["updated_at"] = fin
        row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_executions.json", execs)
        return _err("UNAUTHORIZED", row["error_message"], execution_id=exec_id)

    # Offline: return synthetic list, but do not fabricate datastore rows beyond result_data.
    # We provide deterministic-ish sample summaries as a stand-in for AppleScript output.
    # This still records an execution row.
    def _fake_msg(i):
        msg_id = "msg_" + uuid.uuid4().hex[:16]
        days_ago = random.randint(0, 14)
        date = _isoz(datetime.datetime.utcnow() - datetime.timedelta(days=days_ago, hours=random.randint(0, 23)))
        unread = random.choice([True, False])
        return {
            "id": msg_id,
            "subject": f"Sample message {i+1}",
            "from": "sender@example.com",
            "to": recipient if False else "me@example.com",
            "date": date,
            "mailbox": mailbox,
            "account": account,
            "unread": unread
        }

    msgs = []
    i = 0
    while len(msgs) < count_int:
        m = _fake_msg(i)
        i += 1
        if unreadOnly is True and not m["unread"]:
            continue
        msgs.append(m)

    fin = _isoz(datetime.datetime.utcnow())
    row["status"] = "succeeded"
    row["result_data"] = {
        "ok": True,
        "mailbox": mailbox,
        "account": account,
        "count": len(msgs),
        "messages": msgs
    }
    row["finished_at"] = fin
    row["updated_at"] = fin
    row["duration_ms"] = int((time.time() - t0) * 1000)

    key["last_used_at"] = fin
    key["updated_at"] = fin

    _save("api_keys.json", keys)
    _save("tool_executions.json", execs)

    return {
        "execution_id": exec_id,
        "tool_name": TOOL,
        "status": row["status"],
        "result": row["result_data"]
    }

def mail_get_email(mailbox=None, account=None, subject=None, sender=None, dateReceived=None, unreadOnly=None, includeBody=None, host_device_id=None, api_key=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(exec_row):
        exec_row["updated_at"] = now_iso
        _save("tool_executions.json", execs + [exec_row])

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _find_key_and_client(api_key_param):
        keys = _load("api_keys.json")
        clients = _load("api_clients.json")
        # authenticate by id or client-visible key_prefix (not key_hash)
        candidates = []
        if api_key_param is None:
            # ambient: any active, unexpired key for an active client may be used
            for k in keys:
                if k.get("status") != "active":
                    continue
                exp = _parse_dt(k.get("expires_at"))
                if exp and exp <= now:
                    continue
                c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
                if not c or c.get("status") != "active":
                    continue
                candidates.append((k, c))
        else:
            if not isinstance(api_key_param, str) or not api_key_param.strip():
                return None, None
            token = api_key_param.strip()
            for k in keys:
                if k.get("id") == token or k.get("key_prefix") == token:
                    c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
                    candidates.append((k, c))
        # choose a working combination: active client, active key, not expired
        for k, c in candidates:
            if not k or not c:
                continue
            if c.get("status") != "active":
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp and exp <= now:
                continue
            return k, c
        return None, None

    execs = _load("tool_executions.json")
    host_ids = set()
    for e in execs:
        hid = e.get("host_device_id")
        if isinstance(hid, str) and hid:
            host_ids.add(hid)

    tool_name = "mail_get_email"
    exec_row = {
        "id": _new_id("exec"),
        "client_id": None,
        "api_key_id": None,
        "tool_name": tool_name,
        "status": "queued",
        "request_params": {},
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": host_device_id,
        "duration_ms": None,
        "normalized": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "started_at": None,
        "finished_at": None
    }

    # host_device_id validation (must match configured host identities)
    if not isinstance(host_device_id, str) or not host_device_id.strip() or (len(host_ids) > 0 and host_device_id not in host_ids):
        exec_row["status"] = "failed"
        exec_row["error_type"] = "validation_error"
        exec_row["error_message"] = "host_device_id is missing or not a configured host identity"
        exec_row["finished_at"] = now_iso
        exec_row["duration_ms"] = int((time.time() - t0) * 1000)
        _log(exec_row)
        return _err("VALIDATION_ERROR", exec_row["error_message"])

    api_k, api_c = _find_key_and_client(api_key)
    if not api_k or not api_c:
        exec_row["status"] = "failed"
        exec_row["error_type"] = "unauthorized"
        exec_row["error_message"] = "No active, unexpired API key for an active client could be resolved"
        exec_row["finished_at"] = now_iso
        exec_row["duration_ms"] = int((time.time() - t0) * 1000)
        _log(exec_row)
        return _err("UNAUTHORIZED", exec_row["error_message"])

    exec_row["client_id"] = api_c.get("id")
    exec_row["api_key_id"] = api_k.get("id")

    # Quota enforcement (all_tools + tool-specific)
    quotas = _load("usage_quotas.json")
    active_quotas = [q for q in quotas if q.get("status") == "active" and q.get("client_id") == api_c.get("id")]
    relevant = []
    for q in active_quotas:
        if q.get("scope") == "all_tools" and q.get("tool_name") is None:
            relevant.append(q)
        elif q.get("scope") == "tool" and q.get("tool_name") == tool_name:
            relevant.append(q)

    for q in relevant:
        ws = q.get("window_seconds")
        mx = q.get("max_requests")
        if not isinstance(ws, int) or ws < 1 or ws > 86400 or not isinstance(mx, int) or mx < 1 or mx > 100000:
            continue
        window_start = now - datetime.timedelta(seconds=ws)
        cnt = 0
        for e in execs:
            if e.get("client_id") != api_c.get("id"):
                continue
            if q.get("scope") == "tool" and e.get("tool_name") != tool_name:
                continue
            ca = _parse_dt(e.get("created_at"))
            if ca and ca >= window_start:
                cnt += 1
        # include this incoming call
        if cnt + 1 > mx:
            exec_row["status"] = "failed"
