        if api_key_param is None:
            for k in keys:
                if k.get("status") != "active":
                    continue
                exp = _parse_dt(k.get("expires_at"))
                if exp and exp <= now:
                    continue
                c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
                if not c or c.get("status") != "active":
                    continue
                candidates.append((k, c))
        else:
            if not isinstance(api_key_param, str) or not api_key_param.strip():
                return None, None
