            for k in keys:
                if k.get("id") == token or k.get("key_prefix") == token:
                    c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
                    candidates.append((k, c))
        for k, c in candidates:
            if not k or not c:
                continue
            if c.get("status") != "active":
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp and exp <= now:
