    for q in relevant:
        ws = q.get("window_seconds")
        mx = q.get("max_requests")
        if not isinstance(ws, int) or ws < 1 or ws > 86400 or not isinstance(mx, int) or mx < 1 or mx > 100000:
            continue
        window_start = now - datetime.timedelta(seconds=ws)
        cnt = 0
        for e in execs:
            if e.get("client_id") != api_c.get("id"):
                continue
            if q.get("scope") == "tool" and e.get("tool_name") != tool_name:
                continue
            ca = _parse_dt(e.get("created_at"))
            if ca and ca >= window_start:
                cnt += 1
        if cnt + 1 > mx:
            exec_row["request_params"] = {"content": content}
            exec_row["error_type"] = "quota_exceeded"
            exec_row["error_message"] = "Quota exceeded for the requested window"
            exec_row["status"] = "failed"
            exec_row["finished_at"] = now_iso
            exec_row["duration_ms"] = int((time.time() - t0) * 1000)
            _save("tool_executions.json", execs + [exec_row])
            return _err("QUOTA_EXCEEDED", exec_row["error_message"], quota={"id": q.get("id"), "window_seconds": ws, "max_requests": mx})

