def shortcuts_list_shortcuts(limit=None, host_device_id=None, api_key=None, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _find_key_and_client(api_key_param):
        keys = _load("api_keys.json")
        clients = _load("api_clients.json")
        candidates = []
        if api_key_param is None:
            for k in keys:
                if k.get("status") != "active":
                    continue
                exp = _parse_dt(k.get("expires_at"))
                if exp and exp <= now:
                    continue
                c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
                if not c or c.get("status") != "active":
                    continue
                candidates.append((k, c))
        else:
            if not isinstance(api_key_param, str) or not api_key_param.strip():
                return None, None
            token = api_key_param.strip()
            for k in keys:
                if k.get("id") == token or k.get("key_prefix") == token:
                    c = next((cc for cc in clients if cc.get("id") == k.get("client_id")), None)
                    candidates.append((k, c))
        for k, c in candidates:
            if not k or not c:
                continue
            if c.get("status") != "active":
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp and exp <= now:
                continue
            return k, c
        return None, None

    execs = _load("tool_executions.json")
    host_ids = set()
    for e in execs:
        hid = e.get("host_device_id")
        if isinstance(hid, str) and hid:
            host_ids.add(hid)

    tool_name = "shortcuts_list_shortcuts"
    exec_row = {
        "id": _new_id("exec"),
        "client_id": None,
        "api_key_id": None,
        "tool_name": tool_name,
        "status": "queued",
        "request_params": {},
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": host_device_id,
        "duration_ms": None,
        "normalized": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "started_at": None,
        "finished_at": None
    }

    def _persist_failed(api_code, msg, err_type):
        exec_row["status"] = "failed"
        exec_row["error_type"] = err_type
        exec_row["error_message"] = msg
        exec_row["finished_at"] = now_iso
        exec_row["duration_ms"] = int((time.time() - t0) * 1000)
        exec_row["updated_at"] = now_iso
        _save("tool_executions.json", execs + [exec_row])
        return _err(api_code, msg)

    if not isinstance(host_device_id, str) or not host_device_id.strip() or (len(host_ids) > 0 and host_device_id not in host_ids):
        exec_row["request_params"] = {"limit": limit}
        return _persist_failed("VALIDATION_ERROR", "host_device_id is missing or not a configured host identity", "validation_error")

    api_k, api_c = _find_key_and_client(api_key)
    if not api_k or not api_c:
        exec_row["request_params"] = {"limit": limit}
        return _persist_failed("UNAUTHORIZED", "No active, unexpired API key for an active client could be resolved", "unauthorized")

    exec_row["client_id"] = api_c.get("id")
    exec_row["api_key_id"] = api_k.get("id")

    # Validate limit per schema: if present must be 1..500 (integer-like)
    eff_limit = None
    if limit is not None:
        if isinstance(limit, bool):
            exec_row["request_params"] = {"limit": limit}
            return _persist_failed("VALIDATION_ERROR", "limit must be a number between 1 and 500", "validation_error")
        if not isinstance(limit, (int, float)) or (isinstance(limit, float) and (math.isnan(limit) or math.isinf(limit))):
            exec_row["request_params"] = {"limit": limit}
            return _persist_failed("VALIDATION_ERROR", "limit must be a number between 1 and 500", "validation_error")
        if int(limit) != limit and not isinstance(limit, int):
            # allow 10.0 but not 10.5
            if abs(limit - int(limit)) > 0:
                exec_row["request_params"] = {"limit": limit}
                return _persist_failed("VALIDATION_ERROR", "limit must be integer-like", "validation_error")
        eff_limit = int(limit)
        if eff_limit < 1 or eff_limit > 500:
            exec_row["request_params"] = {"limit": limit}
            return _persist_failed("VALIDATION_ERROR", "limit must be between 1 and 500", "validation_error")

    exec_row["request_params"] = {"limit": eff_limit}

    # Quotas
    quotas = _load("usage_quotas.json")
    active_quotas = [q for q in quotas if q.get("status") == "active" and q.get("client_id") == api_c.get("id")]
    relevant = []
    for q in active_quotas:
        if q.get("scope") == "all_tools" and q.get("tool_name") is None:
            relevant.append(q)
        elif q.get("scope") == "tool" and q.get("tool_name") == tool_name:
            relevant.append(q)
    for q in relevant:
        ws = q.get("window_seconds")
        mx = q.get("max_requests")
        if not isinstance(ws, int) or ws < 1 or ws > 86400 or not isinstance(mx, int) or mx < 1 or mx > 100000:
            continue
        window_start = now - datetime.timedelta(seconds=ws)
        cnt = 0
        for e in execs:
            if e.get("client_id") != api_c.get("id"):
                continue
            if q.get("scope") == "tool" and e.get("tool_name") != tool_name:
                continue
            ca = _parse_dt(e.get("created_at"))
            if ca and ca >= window_start:
                cnt += 1
        if cnt + 1 > mx:
            exec_row["error_type"] = "quota_exceeded"
            exec_row["error_message"] = "Quota exceeded for the requested window"
            exec_row["status"] = "failed"
            exec_row["finished_at"] = now_iso
            exec_row["duration_ms"] = int((time.time() - t0) * 1000)
            _save("tool_executions.json", execs + [exec_row])
            return _err("QUOTA_EXCEEDED", exec_row["error_message"], quota={"id": q.get("id"), "window_seconds": ws, "max_requests": mx})

    # Policy (default deny)
    policies = _load("tool_policies.json")
    pol = next((p for p in policies if p.get("client_id") == api_c.get("id") and p.get("tool_name") == tool_name and p.get("status") == "active"), None)
    if not pol or pol.get("effect") != "allow":
        exec_row["status"] = "failed"
        exec_row["error_type"] = "policy_denied"
        exec_row["error_message"] = "Tool access denied by policy"
        exec_row["finished_at"] = now_iso
        exec_row["duration_ms"] = int((time.time() - t0) * 1000)
        _save("tool_executions.json", execs + [exec_row])
        return _err("CONFLICT", exec_row["error_message"], reason="policy_denied")

    # running -> succeeded; offline: return empty list (no shortcuts inventory in datastore)
    exec_row["status"] = "running"
    exec_row["started_at"] = now_iso

    # Update key last_used_at
    keys_all = _load("api_keys.json")
    for k in keys_all:
        if k.get("id") == api_k.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys_all)

    shortcuts = []
    if eff_limit is not None:
        shortcuts = shortcuts[:eff_limit]

    exec_row["status"] = "succeeded"
    exec_row["finished_at"] = now_iso
    exec_row["duration_ms"] = int((time.time() - t0) * 1000)
    exec_row["result_data"] = {"shortcuts": shortcuts, "count": len(shortcuts)}
    exec_row["updated_at"] = now_iso
    _save("tool_executions.json", execs + [exec_row])

    return {
        "execution_id": exec_row["id"],
        "tool_name": tool_name,
        "status": exec_row["status"],
        "shortcuts": shortcuts,
        "count": len(shortcuts)
    }

def messages_list_chats(includeParticipantDetails=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _tool_enum_ok(name):
        tools = {
            "system_volume", "system_get_frontmost_app", "system_launch_app", "system_quit_app",
            "system_toggle_dark_mode", "system_get_battery_status", "calendar_add", "calendar_list",
            "finder_get_selected_files", "finder_search_files", "finder_quick_look_file",
            "clipboard_get_clipboard", "clipboard_set_clipboard", "clipboard_clear_clipboard",
            "notifications_toggle_do_not_disturb", "notifications_send_notification",
            "iterm_paste_clipboard", "iterm_run", "mail_create_email", "mail_list_emails",
            "mail_get_email", "pages_create_document", "shortcuts_run_shortcut",
            "shortcuts_list_shortcuts", "messages_list_chats", "messages_get_messages",
            "messages_search_messages", "messages_compose_message", "notes_create",
            "notes_createRawHtml", "notes_list", "notes_get", "notes_search"
        }
        return name in tools

    TOOL_NAME = "messages_list_chats"
    if not _tool_enum_ok(TOOL_NAME):
        return _err("VALIDATION_ERROR", "Unknown tool name")

    t0 = time.time()

    # Validate inputs
    if includeParticipantDetails is None:
        includeParticipantDetails = False
    if not isinstance(includeParticipantDetails, bool):
        return _err("VALIDATION_ERROR", "includeParticipantDetails must be a boolean")

    host_device_id = _extra.get("host_device_id")
    hosts = _load("host_devices.json")
    host_ok = isinstance(host_device_id, str) and host_device_id and any(
        isinstance(h, dict) and h.get("id") == host_device_id and h.get("status", "active") == "active"
        for h in hosts
    )

    keys = _load("api_keys.json")
    clients = _load("api_clients.json")

    provided_cred = _extra.get("api_key") if "api_key" in _extra else _extra.get("api_key_id")
    key_row = None
    client_row = None

    def _client_by_id(cid):
        for c in clients:
            if isinstance(c, dict) and c.get("id") == cid:
                return c
        return None

    # Authenticate: explicit credential required by business rules.
    if isinstance(provided_cred, str) and provided_cred:
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == provided_cred or k.get("key_prefix") == provided_cred:
                c = _client_by_id(k.get("client_id"))
                if not c:
                    continue
                if c.get("status") != "active":
                    continue
                if k.get("status") != "active":
                    continue
                exp = _parse_dt(k.get("expires_at"))
                if exp is not None and exp <= _now():
                    continue
                key_row = k
                client_row = c
                break

    if not client_row:
        # Log failed execution as UNAUTHORIZED
        execs = _load("tool_executions.json")
        now = _now()
        exec_row = {
            "id": _gen_id("exec"),
            "client_id": None,
            "api_key_id": None,
            "tool_name": TOOL_NAME,
            "status": "failed",
            "request_params": {"includeParticipantDetails": includeParticipantDetails},
            "result_data": None,
            "error_type": "unauthorized",
            "error_message": "Missing/invalid/expired API key or inactive client",
            "host_device_id": host_device_id if isinstance(host_device_id, str) else "",
            "duration_ms": int((time.time() - t0) * 1000),
            "normalized": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "started_at": _iso(now),
            "finished_at": _iso(now),
        }
        execs.append(exec_row)
        _save("tool_executions.json", execs)
        return _err("UNAUTHORIZED", "Missing/invalid/expired API key or inactive client")

    # Host validation (must be present and configured)
    if not host_ok:
        execs = _load("tool_executions.json")
        now = _now()
        exec_row = {
            "id": _gen_id("exec"),
            "client_id": client_row["id"],
            "api_key_id": key_row.get("id"),
            "tool_name": TOOL_NAME,
            "status": "failed",
            "request_params": {"includeParticipantDetails": includeParticipantDetails},
            "result_data": None,
            "error_type": "validation_error",
            "error_message": "host_device_id is missing or not a configured active host",
            "host_device_id": host_device_id if isinstance(host_device_id, str) else "",
            "duration_ms": int((time.time() - t0) * 1000),
            "normalized": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "started_at": _iso(now),
            "finished_at": _iso(now),
        }
        execs.append(exec_row)
        _save("tool_executions.json", execs)
        return _err("VALIDATION_ERROR", "host_device_id is missing or not a configured active host")

    # Evaluate policy: default deny
    policies = _load("tool_policies.json")
    pol = None
    for p in policies:
        if not isinstance(p, dict):
            continue
        if p.get("client_id") == client_row["id"] and p.get("tool_name") == TOOL_NAME and p.get("status") == "active":
            pol = p
            break

    if not pol or pol.get("effect") != "allow":
        execs = _load("tool_executions.json")
        now = _now()
        exec_row = {
            "id": _gen_id("exec"),
            "client_id": client_row["id"],
            "api_key_id": key_row.get("id"),
            "tool_name": TOOL_NAME,
            "status": "failed",
            "request_params": {"includeParticipantDetails": includeParticipantDetails},
            "result_data": None,
            "error_type": "policy_denied",
            "error_message": "Tool use is not permitted by policy",
            "host_device_id": host_device_id,
            "duration_ms": int((time.time() - t0) * 1000),
            "normalized": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "started_at": _iso(now),
            "finished_at": _iso(now),
        }
        execs.append(exec_row)
        _save("tool_executions.json", execs)
        return _err("UNAUTHORIZED", "Client is not permitted to use this tool")

    # Quota enforcement
    quotas = _load("usage_quotas.json")
    execs = _load("tool_executions.json")
    now = _now()

    def _count_within(window_seconds, tool_name=None):
        cutoff = now - datetime.timedelta(seconds=window_seconds)
        n = 0
        for e in execs:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_row["id"]:
                continue
            if tool_name is not None and e.get("tool_name") != tool_name:
                continue
            created = _parse_dt(e.get("created_at"))
            if created and created >= cutoff:
                n += 1
        return n

    for q in quotas:
        if not isinstance(q, dict):
            continue
        if q.get("client_id") != client_row["id"] or q.get("status") != "active":
            continue
        scope = q.get("scope")
        ws = q.get("window_seconds")
        mx = q.get("max_requests")
        if not isinstance(ws, int) or not (1 <= ws <= 86400):
            continue
        if not isinstance(mx, int) or not (1 <= mx <= 100000):
            continue
        if scope == "all_tools":
            if _count_within(ws, tool_name=None) + 1 > mx:
                exec_row = {
                    "id": _gen_id("exec"),
                    "client_id": client_row["id"],
                    "api_key_id": key_row.get("id"),
                    "tool_name": TOOL_NAME,
                    "status": "failed",
                    "request_params": {"includeParticipantDetails": includeParticipantDetails},
                    "result_data": None,
                    "error_type": "quota_exceeded",
                    "error_message": "Quota exceeded",
                    "host_device_id": host_device_id,
                    "duration_ms": int((time.time() - t0) * 1000),
                    "normalized": None,
                    "created_at": _iso(now),
                    "updated_at": _iso(now),
                    "started_at": _iso(now),
                    "finished_at": _iso(now),
                }
                execs.append(exec_row)
                _save("tool_executions.json", execs)
                return _err("QUOTA_EXCEEDED", "Quota exceeded")
        elif scope == "tool" and q.get("tool_name") == TOOL_NAME:
            if _count_within(ws, tool_name=TOOL_NAME) + 1 > mx:
                exec_row = {
                    "id": _gen_id("exec"),
                    "client_id": client_row["id"],
                    "api_key_id": key_row.get("id"),
                    "tool_name": TOOL_NAME,
                    "status": "failed",
                    "request_params": {"includeParticipantDetails": includeParticipantDetails},
                    "result_data": None,
                    "error_type": "quota_exceeded",
                    "error_message": "Quota exceeded",
                    "host_device_id": host_device_id,
                    "duration_ms": int((time.time() - t0) * 1000),
                    "normalized": None,
                    "created_at": _iso(now),
                    "updated_at": _iso(now),
                    "started_at": _iso(now),
                    "finished_at": _iso(now),
                }
                execs.append(exec_row)
                _save("tool_executions.json", execs)
                return _err("QUOTA_EXCEEDED", "Quota exceeded")

    # Create execution record and "execute"
    exec_row = {
        "id": _gen_id("exec"),
        "client_id": client_row["id"],
        "api_key_id": key_row.get("id"),
        "tool_name": TOOL_NAME,
        "status": "running",
        "request_params": {"includeParticipantDetails": includeParticipantDetails},
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": host_device_id,
        "duration_ms": None,
        "normalized": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
        "started_at": _iso(now),
        "finished_at": None,
    }
    execs.append(exec_row)

    # Update last_used_at
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", keys)

    # Read chat data from datastore
    chats = _load("messages_chats.json")
    participants = _load("messages_participants.json")

    chat_summaries = []
    if isinstance(chats, list):
        for ch in chats:
            if not isinstance(ch, dict):
                continue
            item = {
                "chatId": ch.get("id") or ch.get("chat_id"),
                "displayName": ch.get("display_name") or ch.get("name") or "",
                "service": ch.get("service") or "Messages",
                "lastMessageAt": ch.get("last_message_at") or ch.get("updated_at") or None,
                "participantIds": ch.get("participant_ids") if isinstance(ch.get("participant_ids"), list) else [],
            }
            if includeParticipantDetails:
                det = []
                for pid in item["participantIds"]:
                    pr = None
                    for p in participants:
                        if isinstance(p, dict) and (p.get("id") == pid or p.get("participant_id") == pid):
                            pr = p
                            break
                    if pr:
                        det.append({
                            "id": pr.get("id") or pr.get("participant_id") or pid,
                            "handle": pr.get("handle") or pr.get("address") or "",
                            "displayName": pr.get("display_name") or pr.get("name") or "",
                            "service": pr.get("service") or ch.get("service") or "Messages",
                        })
                    else:
                        det.append({"id": pid, "handle": "", "displayName": "", "service": ch.get("service") or "Messages"})
                item["participants"] = det
            chat_summaries.append(item)

    # Succeed execution
    finished = _now()
    exec_row["status"] = "succeeded"
    exec_row["result_data"] = {"chats": chat_summaries}
    exec_row["duration_ms"] = int((time.time() - t0) * 1000)
    exec_row["updated_at"] = _iso(finished)
    exec_row["finished_at"] = _iso(finished)
    _save("tool_executions.json", execs)

    return {
        "chats": chat_summaries,
        "execution": {"id": exec_row["id"], "status": exec_row["status"], "duration_ms": exec_row["duration_ms"]},
    }

