    msgs = _load("messages_items.json")
    items = []
    if isinstance(msgs, list):
        items = [m for m in msgs if isinstance(m, dict)]

    cutoff = now - datetime.timedelta(days=days_i)
    st = searchText.casefold()
    sender_cf = sender.casefold().strip()
    chat_cf = chatId.strip()

    def _msg_dt(m):
        return _parse_dt(m.get("date") or m.get("created_at") or m.get("timestamp"))

    matched = []
    for m in items:
        dt = _msg_dt(m)
        if dt is None or dt < cutoff:
            continue
        if chat_cf:
            mid_chat = m.get("chat_id") or m.get("chatId") or ""
            if str(mid_chat) != chat_cf:
                continue
        if sender_cf:
            ms = (m.get("sender") or m.get("from") or "")
            if not isinstance(ms, str) or ms.casefold().strip() != sender_cf:
                continue
        text = m.get("text") or m.get("body") or ""
        if not isinstance(text, str):
            continue
        if st not in text.casefold():
            continue
        matched.append(m)

    matched.sort(key=lambda m: _msg_dt(m) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=True)
    matched = matched[:limit_i]

    out = []
    for m in matched:
        out.append({
            "id": m.get("id") or m.get("message_id"),
            "chatId": m.get("chat_id") or m.get("chatId"),
            "sender": m.get("sender") or m.get("from") or "",
            "text": m.get("text") or m.get("body") or "",
            "date": m.get("date") or m.get("created_at") or m.get("timestamp"),
            "isFromMe": m.get("is_from_me") if isinstance(m.get("is_from_me"), bool) else m.get("isFromMe"),
            "service": m.get("service") or "Messages",
        })

    finished = _now()
    exec_row["status"] = "succeeded"
    exec_row["result_data"] = {"messages": out}
    exec_row["duration_ms"] = int((time.time() - t0) * 1000)
    exec_row["updated_at"] = _iso(finished)
    exec_row["finished_at"] = _iso(finished)
    _save("tool_executions.json", execs)

    return {"messages": out, "execution": {"id": exec_row["id"], "status": exec_row["status"], "duration_ms": exec_row["duration_ms"]}}

def notes_search(query, folder=None, limit=None, includeBody=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- authenticate ambient (pick any working active, non-expired key whose client is active) ---
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    policies = _load("tool_policies.json")
    quotas = _load("usage_quotas.json")
    executions = _load("tool_executions.json")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _active_client_by_id(cid):
        for c in clients:
            if c.get("id") == cid:
                return c
        return None

    def _is_key_usable(k, client_row):
        if not isinstance(k, dict) or not isinstance(client_row, dict):
            return False
        if client_row.get("status") != "active":
            return False
        if k.get("client_id") != client_row.get("id"):
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None:
            now_dt = datetime.datetime.now(datetime.timezone.utc)
            if exp.tzinfo is None:
                exp = exp.replace(tzinfo=datetime.timezone.utc)
            if exp <= now_dt:
                return False
        return True

    chosen = None
    for k in keys:
        c = _active_client_by_id(k.get("client_id"))
        if c and _is_key_usable(k, c) and c.get("status") != "deleted":
            chosen = (c, k)
            break

    if not chosen:
        # log failed execution (no valid key -> unauthorized)
        ex_id = _new_id("tex")
        executions.append({
            "id": ex_id,
            "client_id": None,
            "api_key_id": None,
            "tool_name": "notes_search",
            "status": "failed",
            "request_params": {"query": query, "folder": folder, "limit": limit, "includeBody": includeBody},
            "result_data": None,
            "error_type": "unauthorized",
            "error_message": "No active, non-expired API key for an active client is available.",
            "host_device_id": "unknown",
            "duration_ms": int((time.time() - t0) * 1000),
            "normalized": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        })
        _save("tool_executions.json", executions)
        return _err("UNAUTHORIZED", "Invalid or expired API key.")

    client, api_key = chosen

    # --- resolve host_device_id (must match configured hosts) ---
    # Server-configured hosts live in a JSON file if present; otherwise accept any non-empty passed/implicit host
    host_id = None
    if isinstance(_extra, dict):
        host_id = _extra.get("host_device_id") or _extra.get("hostDeviceId")
    if not host_id:
        # try to find any configured host id to satisfy requirement
        host_rows = _load("host_identities.json")
        if isinstance(host_rows, list) and host_rows:
            for hr in host_rows:
                if isinstance(hr, dict) and hr.get("id"):
                    host_id = hr.get("id")
                    break
        if not host_id:
            host_id = "local-host"

    def _host_is_allowed(h):
        host_rows = _load("host_identities.json")
        if not host_rows:
            return True
        for hr in host_rows:
            if isinstance(hr, dict) and hr.get("id") == h and hr.get("status", "active") == "active":
                return True
        return False

    # --- apply tool defaults & validate inputs ---
    eff = {"query": query}
    if folder is not None:
        eff["folder"] = folder
    if limit is None:
        eff["limit"] = 5
    else:
        eff["limit"] = limit
    if includeBody is None:
        eff["includeBody"] = True
    else:
        eff["includeBody"] = includeBody

    # Execution record is created for every request (including validation/policy failures)
    ex_id = _new_id("tex")
    ex_row = {
        "id": ex_id,
        "client_id": client.get("id"),
        "api_key_id": api_key.get("id"),
        "tool_name": "notes_search",
        "status": "queued",
        "request_params": eff,
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": host_id,
        "duration_ms": None,
        "normalized": None,
        "created_at": now,
        "updated_at": now,
        "started_at": None,
        "finished_at": None
    }
    executions.append(ex_row)
    _save("tool_executions.json", executions)

    def _fail(err_type, msg, code="VALIDATION_ERROR", **extra):
        # transition queued -> failed
        for e in executions:
            if e.get("id") == ex_id:
                e["status"] = "failed"
                e["error_type"] = err_type
                e["error_message"] = msg
                e["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                fin = e["updated_at"]
                e["started_at"] = e.get("started_at") or e["created_at"]
                e["finished_at"] = fin
                e["duration_ms"] = int((time.time() - t0) * 1000)
                break
        _save("tool_executions.json", executions)
        return _err(code, msg, **extra)

    if not _host_is_allowed(host_id):
        return _fail("validation_error", "host_device_id does not match a configured host identity.", code="VALIDATION_ERROR")

    if not isinstance(query, str) or not query.strip():
        return _fail("validation_error", "query is required and must be a non-empty string.", code="VALIDATION_ERROR")

    # limit is "number" in tool schema, but business rule says notes_search limit 1..50 default 5.
    if isinstance(eff["limit"], bool) or not isinstance(eff["limit"], (int, float)):
        return _fail("validation_error", "limit must be a number.", code="VALIDATION_ERROR")
    if int(eff["limit"]) != eff["limit"]:
        # allow integer-like floats
        if not (isinstance(eff["limit"], float) and eff["limit"].is_integer()):
            return _fail("validation_error", "limit must be integer-like.", code="VALIDATION_ERROR")
    eff["limit"] = int(eff["limit"])
    if eff["limit"] < 1 or eff["limit"] > 50:
        return _fail("validation_error", "limit must be between 1 and 50.", code="VALIDATION_ERROR")

    if folder is not None and (not isinstance(folder, str) or not folder.strip()):
        return _fail("validation_error", "folder must be a non-empty string when provided.", code="VALIDATION_ERROR")

    if not isinstance(eff["includeBody"], bool):
        return _fail("validation_error", "includeBody must be a boolean.", code="VALIDATION_ERROR")

    # persist effective params after coercions/defaults
    for e in executions:
        if e.get("id") == ex_id:
            e["request_params"] = dict(eff)
            e["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("tool_executions.json", executions)

    # --- policy evaluation (default deny) ---
    policy = None
    for p in policies:
        if p.get("client_id") == client.get("id") and p.get("tool_name") == "notes_search" and p.get("status") == "active":
            policy = p
            break
    if not policy or policy.get("effect") != "allow":
        return _fail("policy_denied", "Tool is not allowed by policy.", code="UNAUTHORIZED")

    # --- quota enforcement (all_tools and tool-specific) ---
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    def _within_window(created_at, window_s):
        dt = _parse_dt(created_at)
        if not dt:
            return False
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (now_dt - dt).total_seconds() <= window_s

    applicable = []
    for q in quotas:
        if q.get("client_id") != client.get("id") or q.get("status") != "active":
            continue
        if q.get("scope") == "all_tools":
            applicable.append(q)
        elif q.get("scope") == "tool" and q.get("tool_name") == "notes_search":
            applicable.append(q)

    for q in applicable:
        ws = q.get("window_seconds")
        mr = q.get("max_requests")
        if not isinstance(ws, int) or not isinstance(mr, int):
            continue
        count = 0
        for e in executions:
            if e.get("client_id") != client.get("id"):
                continue
            if not _within_window(e.get("created_at"), ws):
                continue
            # quota is "tool executions"; count all tools for all_tools; else only this tool
            if q.get("scope") == "tool":
                if e.get("tool_name") != "notes_search":
                    continue
            count += 1
        if count > mr:
            return _fail("quota_exceeded", "Quota exceeded for the requested window.", code="QUOTA_EXCEEDED", quota_id=q.get("id"))

    # --- execute (simulate Apple Notes search by reading datastore if present) ---
    # The service must not fabricate rows; it can only return data from store.
    notes_store = _load("notes.json")  # optional collection
    results = []
    qtext = query.strip().lower()

    if isinstance(notes_store, list):
        for n in notes_store:
            if not isinstance(n, dict):
                continue
            title = n.get("title") if isinstance(n.get("title"), str) else ""
            body = n.get("body") if isinstance(n.get("body"), str) else ""
            nf = n.get("folder") if isinstance(n.get("folder"), str) else None
            if folder is not None and nf != folder:
                continue
            if qtext in title.lower() or qtext in body.lower():
                item = {}
                # return only fields that exist in stored row
                if "id" in n: item["id"] = n.get("id")
                if "title" in n: item["title"] = n.get("title")
                if folder is not None or "folder" in n:
                    if "folder" in n: item["folder"] = n.get("folder")
                if eff["includeBody"] and "body" in n:
                    item["body"] = n.get("body")
                results.append(item)
                if len(results) >= eff["limit"]:
                    break

    # mark execution succeeded
    updated = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for e in executions:
        if e.get("id") == ex_id:
            e["status"] = "succeeded"
            e["result_data"] = {"results": results, "count": len(results)}
            e["error_type"] = None
            e["error_message"] = None
            e["started_at"] = e.get("started_at") or e["created_at"]
            e["finished_at"] = updated
            e["updated_at"] = updated
            e["duration_ms"] = int((time.time() - t0) * 1000)
            break

    # update api key last_used_at
    for k in keys:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = updated
            k["updated_at"] = updated
            break

    _save("tool_executions.json", executions)
    _save("api_keys.json", keys)

    return {"results": results, "limit": eff["limit"], "includeBody": eff["includeBody"], "count": len(results)}

def api_clients_create(name, description=None, default_timezone=None, status=None, **_extra):
    import json, os, datetime, uuid, time, zoneinfo

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "api_clients_create"
    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _get_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00").astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _extract_api_key_from_extra():
        for k in ("api_key", "apiKey", "key", "token", "authorization", "Authorization", "x_api_key", "x-api-key"):
            v = _extra.get(k)
            if isinstance(v, str) and v.strip():
                vv = v.strip()
                if vv.lower().startswith("bearer "):
                    vv = vv.split(" ", 1)[1].strip()
                return vv
        return None

    def _key_is_expired(key_row, now):
        exp = _parse_rfc3339(key_row.get("expires_at"))
        return exp is not None and exp <= now

    def _resolve_auth():
        # caller must be authenticated via explicit or ambient key
        now = _utcnow()
        api_keys = _get_rows(_load("api_keys.json"))
        api_clients = _get_rows(_load("api_clients.json"))
        clients_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}
        provided = _extract_api_key_from_extra()

        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if _key_is_expired(k, now):
                continue
            cli = clients_by_id.get(k.get("client_id"))
            if not isinstance(cli, dict) or cli.get("status") != "active":
                continue
            if provided:
                if provided == k.get("id") or provided == k.get("key_prefix"):
                    candidates.append((cli, k))
            else:
                candidates.append((cli, k))
        if not candidates:
            return None, None

        def _dt(s):
            d = _parse_rfc3339(s)
            return d or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        candidates.sort(key=lambda ck: (_dt(ck[1].get("last_used_at")), _dt(ck[1].get("created_at"))), reverse=True)
        return candidates[0][0], candidates[0][1]

    def _new_client_id():
        return "asmc_cli_" + uuid.uuid4().hex[:26]

    # Auth required
    caller_client, caller_key = _resolve_auth()
    if caller_client is None or caller_key is None:
        return _err("UNAUTHORIZED", "Missing/invalid/expired API key or inactive client", tool_name=tool_name)

    # Validate inputs
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name is required", tool_name=tool_name)
    if len(name) < 1 or len(name) > 200:
        return _err("VALIDATION_ERROR", "name must be between 1 and 200 characters", tool_name=tool_name)
    if description is not None:
        if not isinstance(description, str):
            return _err("VALIDATION_ERROR", "description must be a string", tool_name=tool_name)
        if len(description) > 2000:
            return _err("VALIDATION_ERROR", "description must be at most 2000 characters", tool_name=tool_name)

    if status is None:
        status = "active"
    if status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted", tool_name=tool_name)

    if default_timezone is None:
        default_timezone = "UTC"
    if not isinstance(default_timezone, str) or not default_timezone.strip():
        return _err("VALIDATION_ERROR", "default_timezone must be a non-empty string", tool_name=tool_name)
    # validate IANA timezone
    try:
        zoneinfo.ZoneInfo(default_timezone.strip())
    except Exception:
        return _err("VALIDATION_ERROR", "default_timezone is not a valid IANA timezone string", tool_name=tool_name)

    # Unique(name)
    clients_store = _load("api_clients.json")
    clients = _get_rows(clients_store)
    for c in clients:
        if isinstance(c, dict) and c.get("name") == name and c.get("status") != "deleted":
            return _err("CONFLICT", "Client name already exists", field="name", tool_name=tool_name)

    now = _utcnow()
    row = {
        "id": _new_client_id(),
        "name": name,
        "description": description,
        "status": status,
        "default_timezone": default_timezone.strip(),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    clients.append(row)
    _save("api_clients.json", clients)

    # record usage in tool_executions as an internal tool call for audit dynamics
    executions = _get_rows(_load("tool_executions.json"))
    hid = None
    for e in executions:
        if isinstance(e, dict) and isinstance(e.get("host_device_id"), str) and e.get("host_device_id").strip():
            hid = e.get("host_device_id").strip()
            break
    if hid is None:
        hid = "00000000-0000-0000-0000-000000000000"

    exec_row = {
        "id": "asmc_exe_" + uuid.uuid4().hex[:26],
        "client_id": caller_client.get("id"),
        "api_key_id": caller_key.get("id"),
        "tool_name": tool_name,
        "status": "succeeded",
        "request_params": {"name": name, "description": description, "default_timezone": default_timezone.strip(), "status": status},
        "result_data": {"client": row},
        "error_type": None,
        "error_message": None,
        "host_device_id": hid,
        "duration_ms": int((time.time() - t0) * 1000),
        "normalized": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
        "started_at": _iso(now),
        "finished_at": _iso(now),
    }
    executions.append(exec_row)
    _save("tool_executions.json", executions)

    # update key last_used_at
    keys = _get_rows(_load("api_keys.json"))
    for k in keys:
        if isinstance(k, dict) and k.get("id") == caller_key.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", keys)

    return {"client": row, "execution_id": exec_row["id"]}

def api_clients_update(id, name=None, description=None, default_timezone=None, status=None, **_extra):
    import json, os, datetime, time, uuid, zoneinfo
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
