        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    executions = _load("tool_executions.json")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _active_client_by_id(cid):
        for c in clients:
            if c.get("id") == cid:
                return c
        return None

    def _is_key_usable(k, client_row):
        if client_row.get("status") != "active":
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None:
            now_dt = datetime.datetime.now(datetime.timezone.utc)
            if exp.tzinfo is None:
                exp = exp.replace(tzinfo=datetime.timezone.utc)
            if exp <= now_dt:
                return False
        return True

    chosen = None
    for k in keys:
        c = _active_client_by_id(k.get("client_id"))
        if c and c.get("status") != "deleted" and _is_key_usable(k, c):
            chosen = (c, k)
            break
    if not chosen:
        ex_id = _new_id("tex")
        executions.append({
            "id": ex_id,
            "client_id": None,
            "api_key_id": None,
            "tool_name": "api_clients_update",
            "status": "failed",
            "request_params": {"id": id, "name": name, "description": description, "default_timezone": default_timezone, "status": status},
            "result_data": None,
            "error_type": "unauthorized",
            "error_message": "No active, non-expired API key for an active client is available.",
            "host_device_id": "unknown",
            "duration_ms": int((time.time() - t0) * 1000),
            "normalized": None,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now
        })
        _save("tool_executions.json", executions)
        return _err("UNAUTHORIZED", "Invalid or expired API key.")

    caller_client, api_key = chosen

    # Create execution record (running)
    ex_id = _new_id("tex")
    req_params = {"id": id, "name": name, "description": description, "default_timezone": default_timezone, "status": status}
    executions.append({
        "id": ex_id,
        "client_id": caller_client.get("id"),
        "api_key_id": api_key.get("id"),
        "tool_name": "api_clients_update",
        "status": "running",
        "request_params": req_params,
        "result_data": None,
        "error_type": None,
        "error_message": None,
        "host_device_id": "local-host",
        "duration_ms": None,
        "normalized": None,
        "created_at": now,
        "updated_at": now,
        "started_at": now,
        "finished_at": None
    })
    _save("tool_executions.json", executions)

    def _finish_failed(code, err_type, msg, **extra):
        updated = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for e in executions:
            if e.get("id") == ex_id:
                e["status"] = "failed"
                e["error_type"] = err_type
                e["error_message"] = msg
                e["updated_at"] = updated
                e["finished_at"] = updated
                e["duration_ms"] = int((time.time() - t0) * 1000)
                break
        _save("tool_executions.json", executions)
        return _err(code, msg, **extra)

    # Validate id and locate client
    if not isinstance(id, str) or not id.strip():
        return _finish_failed("VALIDATION_ERROR", "validation_error", "id is required and must be a non-empty string.")

    target = None
    for c in clients:
        if isinstance(c, dict) and c.get("id") == id:
            target = c
            break
    if not target:
        return _finish_failed("NOT_FOUND", "not_found", "API client not found.", client_id=id)

    # Validate fields
    errs = []
    if name is not None:
        if not isinstance(name, str) or not name.strip():
            errs.append("name must be a non-empty string when provided.")
        elif len(name) > 200:
            errs.append("name must be at most 200 characters.")
        else:
            nm_norm = name.strip().lower()
            for c in clients:
                if c is target:
                    continue
                if isinstance(c, dict) and isinstance(c.get("name"), str) and c.get("name").strip().lower() == nm_norm:
                    errs.append("name must be unique.")
                    break

    if description is not None:
        if not isinstance(description, str):
            errs.append("description must be a string when provided.")
        elif len(description) > 2000:
            errs.append("description must be at most 2000 characters.")

    if default_timezone is not None:
        if not isinstance(default_timezone, str) or not default_timezone.strip():
            errs.append("default_timezone must be a non-empty string when provided.")
        else:
            try:
                zoneinfo.ZoneInfo(default_timezone)
            except Exception:
                errs.append("default_timezone must be a valid IANA timezone string.")

    if status is not None:
        if status not in ("active", "suspended", "deleted"):
            errs.append("status must be one of: active, suspended, deleted.")
        else:
            # lifecycle transitions:
            cur = target.get("status")
            transitions = {
                "active": set(["suspended", "deleted"]),
                "suspended": set(["active", "deleted"]),
                "deleted": set([])
            }
            if cur not in transitions:
                errs.append("Current status is invalid.")
            elif status != cur and status not in transitions[cur]:
                return _finish_failed("INVALID_TRANSITION", "validation_error", "Illegal status transition.", from_status=cur, to_status=status)

    if errs:
        return _finish_failed("VALIDATION_ERROR", "validation_error", "Invalid request.", details=errs)

    # Apply updates (idempotent)
    changed = False
    if name is not None and target.get("name") != name.strip():
        target["name"] = name.strip()
        changed = True
    if description is not None and target.get("description") != description:
        target["description"] = description
        changed = True
    if default_timezone is not None and target.get("default_timezone") != default_timezone:
        target["default_timezone"] = default_timezone
        changed = True
    if status is not None and target.get("status") != status:
        target["status"] = status
        changed = True

    if not changed:
        # still a successful mutation (effect is a no-op but matched a row); real APIs often return 200.
        # However contract says "No success without effect" for mutations that matched no row; this matched a row.
        pass

    target["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("api_clients.json", clients)

    updated = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    for e in executions:
        if e.get("id") == ex_id:
            e["status"] = "succeeded"
            e["result_data"] = {"client": target}
            e["updated_at"] = updated
            e["finished_at"] = updated
            e["duration_ms"] = int((time.time() - t0) * 1000)
            break

    for k in keys:
        if k.get("id") == api_key.get("id"):
            k["last_used_at"] = updated
            k["updated_at"] = updated
            break

    _save("tool_executions.json", executions)
    _save("api_keys.json", keys)

    return target

def api_keys_create(client_id, name, expires_at=None, **_extra):
    import json, os, datetime, secrets, string, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", "expires_at must be an RFC3339 timestamp string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", "expires_at must be a valid RFC3339 timestamp", field="expires_at")

    def _gen_id(prefix):
        # deterministic enough for local datastore; avoid collisions by checking
        return f"{prefix}_{secrets.token_hex(16)}"

    def _consteq(a, b):
        try:
            return secrets.compare_digest(a, b)
        except Exception:
            return a == b

    def _find_authenticated_context():
        """
        AUTHENTICATION IS AMBIENT: choose any active, non-expired api_key whose client is active.
        This tool also mentions FORBIDDEN, but schema has no permissions model; any authenticated key can manage keys.
        """
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        now = _now()
        active_clients = {c["id"] for c in clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("id"), str)}
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            if cid not in active_clients:
                continue
            exp = k.get("expires_at")
            if exp is not None:
                # stored as datetime string; treat unparsable as expired
                exp_dt, perr = _parse_rfc3339(exp) if isinstance(exp, str) else (None, True)
                if perr or (exp_dt is None) or (exp_dt <= now):
                    continue
            return {"api_key": k, "client_id": cid}
        return None

    def _envelope(key_row, secret_token):
        # Never return key_hash
        return {
            "api_key": {
                "id": key_row.get("id"),
                "client_id": key_row.get("client_id"),
                "name": key_row.get("name"),
                "key_prefix": key_row.get("key_prefix"),
                "status": key_row.get("status"),
                "last_used_at": key_row.get("last_used_at"),
                "expires_at": key_row.get("expires_at"),
                "created_at": key_row.get("created_at"),
                "updated_at": key_row.get("updated_at"),
            },
            "secret_token": secret_token,
        }

    start = time.time()
    # ---- Validate inputs
    if not isinstance(client_id, str) or not client_id.strip():
        return _err("VALIDATION_ERROR", "client_id must be a non-empty string", field="client_id")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if len(name) < 1 or len(name) > 200:
        return _err("VALIDATION_ERROR", "name length must be between 1 and 200", field="name")
    exp_dt = None
    if expires_at is not None:
        exp_dt, perr = _parse_rfc3339(expires_at)
        if perr:
            return perr

    # ---- Authenticate (ambient)
    ctx = _find_authenticated_context()
    if not ctx:
        return _err("UNAUTHORIZED", "No active, non-expired API key/client available to authenticate this request")

    # ---- Load datastore
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")

    # ---- Find client and validate lifecycle
    client = next((c for c in clients if isinstance(c, dict) and c.get("id") == client_id), None)
    if not client:
        return _err("NOT_FOUND", "API client not found", client_id=client_id)
    if client.get("status") != "active":
        return _err("CONFLICT", "Client must be active to create keys", status=client.get("status"))

    # ---- Enforce constraints: unique(client_id, name), unique(key_prefix), expires_at > created_at
    if any(isinstance(k, dict) and k.get("client_id") == client_id and k.get("name") == name for k in keys):
        return _err("CONFLICT", "API key name must be unique per client", client_id=client_id, name=name)

    created_at_dt = _now()
    if exp_dt is not None and exp_dt <= created_at_dt:
        return _err("VALIDATION_ERROR", "expires_at must be greater than created_at", field="expires_at")

    # Generate secret token (one-time) and store only a hash (cannot authenticate by hash later; but this endpoint doesn't require that)
    # Keep prefix unique globally.
    alphabet = string.ascii_letters + string.digits
    secret_token = "ask_" + "".join(secrets.choice(alphabet) for _ in range(48))
    key_prefix = secret_token[:8]

    # Ensure unique key_prefix (regenerate if collision)
    tries = 0
    while any(isinstance(k, dict) and k.get("key_prefix") == key_prefix for k in keys):
        tries += 1
        if tries > 25:
            return _err("CONFLICT", "Unable to allocate unique key_prefix; please retry")
        secret_token = "ask_" + "".join(secrets.choice(alphabet) for _ in range(48))
        key_prefix = secret_token[:8]

    # Hash with SHA-256 (store as hash string; algorithm label to avoid ambiguity)
    key_hash = "sha256:" + hashlib.sha256(secret_token.encode("utf-8")).hexdigest()

    # Create id unique
    new_id = _gen_id("key")
    while any(isinstance(k, dict) and k.get("id") == new_id for k in keys):
        new_id = _gen_id("key")

    now_iso = _iso(created_at_dt)
    row = {
        "id": new_id,
        "client_id": client_id,
        "name": name,
        "key_prefix": key_prefix,
        "key_hash": key_hash,
        "status": "active",
        "last_used_at": None,
        "expires_at": _iso(exp_dt) if exp_dt is not None else None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    keys.append(row)
    _save("api_keys.json", keys)

    latency_ms = int((time.time() - start) * 1000)
    # No usage/audit collection in schema for these endpoints; only tool_executions apply to tools, not key mgmt.
    return _envelope(row, secret_token)

def api_keys_revoke(id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0043000" if __import__("os").path.isdir("./environment_mix/0043000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "api_keys_revoke"
    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00").astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _get_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _extract_api_key_from_extra():
        for k in ("api_key", "apiKey", "key", "token", "authorization", "Authorization", "x_api_key", "x-api-key"):
            v = _extra.get(k)
            if isinstance(v, str) and v.strip():
                vv = v.strip()
                if vv.lower().startswith("bearer "):
                    vv = vv.split(" ", 1)[1].strip()
                return vv
        return None

    def _key_is_expired(key_row, now):
        exp = _parse_rfc3339(key_row.get("expires_at"))
        return exp is not None and exp <= now

    def _resolve_auth():
        now = _utcnow()
        api_keys = _get_rows(_load("api_keys.json"))
        api_clients = _get_rows(_load("api_clients.json"))
        clients_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}
        provided = _extract_api_key_from_extra()

        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if _key_is_expired(k, now):
                continue
            cli = clients_by_id.get(k.get("client_id"))
            if not isinstance(cli, dict) or cli.get("status") != "active":
                continue
            if provided:
                if provided == k.get("id") or provided == k.get("key_prefix"):
                    candidates.append((cli, k))
            else:
                candidates.append((cli, k))
        if not candidates:
            return None, None

        def _dt(s):
            d = _parse_rfc3339(s)
            return d or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        candidates.sort(key=lambda ck: (_dt(ck[1].get("last_used_at")), _dt(ck[1].get("created_at"))), reverse=True)
        return candidates[0][0], candidates[0][1]

    def _new_exec_id():
        return "asmc_exe_" + uuid.uuid4().hex[:26]

    # validate
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required", tool_name=tool_name)

    caller_client, caller_key = _resolve_auth()
    if caller_client is None or caller_key is None:
        return _err("UNAUTHORIZED", "Missing/invalid/expired API key or inactive client", tool_name=tool_name)

    keys = _get_rows(_load("api_keys.json"))
    target = None
    for k in keys:
        if isinstance(k, dict) and k.get("id") == id:
            target = k
            break
    if target is None:
        return _err("NOT_FOUND", "API key not found", tool_name=tool_name, id=id)

    if target.get("status") == "revoked":
        return _err("VALIDATION_ERROR", "API key is already revoked", tool_name=tool_name, id=id)

    # FORBIDDEN modeled as UNAUTHORIZED/CONFLICT per allowed codes: enforce ownership
    if target.get("client_id") != caller_client.get("id"):
        return _err("UNAUTHORIZED", "Caller cannot manage keys for the owning client", tool_name=tool_name)

    # lifecycle transition active -> revoked
    if target.get("status") != "active":
        return _err("INVALID_TRANSITION", f"Cannot revoke key from status={target.get('status')}", tool_name=tool_name)

    now = _utcnow()
    target["status"] = "revoked"
    target["updated_at"] = _iso(now)

    _save("api_keys.json", keys)

    # audit execution
    executions = _get_rows(_load("tool_executions.json"))
    hid = None
    for e in executions:
        if isinstance(e, dict) and isinstance(e.get("host_device_id"), str) and e.get("host_device_id").strip():
            hid = e.get("host_device_id").strip()
            break
    if hid is None:
        hid = "00000000-0000-0000-0000-000000000000"

    exec_row = {
        "id": _new_exec_id(),
        "client_id": caller_client.get("id"),
        "api_key_id": caller_key.get("id"),
        "tool_name": tool_name,
        "status": "succeeded",
        "request_params": {"id": id},
        "result_data": {"api_key": target},
        "error_type": None,
        "error_message": None,
        "host_device_id": hid,
        "duration_ms": int((time.time() - t0) * 1000),
        "normalized": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
        "started_at": _iso(now),
        "finished_at": _iso(now),
    }
    executions.append(exec_row)
    _save("tool_executions.json", executions)

    # update caller key last_used_at (revoke tool succeeded)
    for k in keys:
        if isinstance(k, dict) and k.get("id") == caller_key.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", keys)

    return {"api_key": target, "execution_id": exec_row["id"]}
